INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (25, 'itIT', 'Tommy Joe,$B$Bil mio cuore diventa sempre più debole ogni ora che passo senza di te. Oh, se solo i nostri congiunti vedessero oltre il male che si sono fatti e si accorgessero che l''unico vero crimine è odiare! L''odio ti consuma e temo che in questi tempi bui prenderà il sopravvento, non solo nelle nostre famiglie. Se riuscissero a capirlo, potremmo stare finalmente insieme. Vivo con la speranza che quel giorno arrivi.$B$BLa tua amata,$BMaybell') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (26, 'itIT', 'Salute William,
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (55, 'itIT', 'Questo è l''atto di proprietà di un terreno nella regione delle Marche Occidentali. Esso conferisce alle seguenti persone il diritto di proprietà dell''area designata, oltre che di tutti gli oggetti prodotti e delle strutture costruite entro i suoi confini.$B$BIl documento è firmato da:$B$BTheodore Ciglioarcuato$BVerna Ciglioarcuato') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (56, 'itIT', '[Le parole in basso sono state scarabocchiate in fretta sul retro dell''atto]$B$BAbbiamo costretto i Ciglioarcuato a cederci il loro atto. Potrebbe tornarti utile nel caso in cui tu decidessi di falsificarne uno per te. I Ciglioarcuato non ci creeranno problemi. L''ultima volta che li ho visti stavano lasciando le Marche Occidentali, prima che il loro carro si rompesse.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (78, 'itIT', 'Questo Buono per un''Armatura può essere usato per un''armatura di cuoio o di stoffa presso la famiglia Timberlain al Campo di Taglio di Vallevante.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (100, 'itIT', 'Proprio quando stavo per criticare la mancanza d''interesse di Ajeck per la strategia di caccia, lei mise mano alla sua faretra, tirò fuori una freccia e la scoccò verso il povero Barnil. Ma non era Barnil il bersaglio di Ajeck. Alle sue spalle infatti giaceva un grosso crocolisco di fiume venuto in superficie, con le fauci spalancate e la freccia di Ajeck conficcata in mezzo ai suoi due grandi occhi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (105, 'itIT', 'Su un precipizio roccioso in alto, definita dalla luce del sole al tramonto, riconobbi la sagoma del predatore felino più grande che avessi mai visto. Riuscii a sparare un colpo con l''archibugio senza mirare, ma il felino non si scompose e ruggì di nuovo, più forte della prima volta, quindi sparì.$B$BRaccogliemmo le nostre cose e facemmo ritorno al campo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (110, 'itIT', 'Sia Ajeck che Ser Erlgadin rimasero calmi, con le armi spianate verso la densa vegetazione alla base degli alberi ondeggianti. Il sole di mezzogiorno picchiava forte sulle nostre teste. Una goccia di sudore scese lentamente sulla tempia di Erlgadin quando tirò indietro il grilletto. Al suono del clic, la fitta vegetazione si diradò e un meraviglioso esemplare di pantera nera si fece avanti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (112, 'itIT', 'L''arma rinculò con violenza tra le sue braccia, andando a sbattere contro l''archibugio di Ajeck, che aveva scelto proprio quel momento per fare fuoco. Partì un colpo maldestro, diretto verso la linea degli alberi. Uno stormo di uccelli si alzò dalle fronde e volò via in ogni direzione, mentre una cortina di fumo si levava dall''albero. Rimanemmo terrorizzati a guardare mentre un enorme ramo si abbatteva sulla pantera in fuga, spezzandole la schiena.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (114, 'itIT', 'Ci mettemmo in marcia alle prime luci dell''alba, diretti a sud, oltre le Rovine di Tkashi. Barnil temeva che ci saremmo imbattuti nei membri della Tribù Scalporosso. Gli spiegai che gli Scalporosso erano impegnati a distruggere la loro tribù rivale, quella dei Fendicranio. Inutile dire che le mie parole non gli furono di alcun sollievo. Tuttavia pensavo che con un archibugio carico, una sacca piena di polvere da sparo e tre cacciatori letali al mio fianco non ci fosse da temere alcuna imboscata nemica.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (115, 'itIT', 'Avevo affrontato un Infernale gigante in battaglia, con l''armata della Legione Infuocata che avanzava da tutte le direzioni. Un gruppo di Troll turbolenti per me era innocuo quanto un coniglio sulle colline di Dun Morogh.
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (119, 'itIT', 'Avevo condotto il gruppo verso il mare, nella speranza che la spiaggia fosse un rifugio sicuro dai raptor. Nella fretta ci eravamo spinti troppo a nord, in posizione elevata e precaria, ma ormai il danno era stato fatto ed era tutta colpa mia. Ci fermammo poco prima di un promontorio a picco, con i raptor che ci inseguivano da vicino.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (120, 'itIT', 'Io feci un passo in avanti, lentamente, con l''arma spianata. Avevo condotto alla morte questi coraggiosi cacciatori e avrei dato la mia vita per difenderli. I Raptor Codafrusta sono creature particolarmente feroci e sanguinarie. Erano molto più numerosi di noi, ma non avrei mai permesso che uccidessero me e i miei compagni senza prima versare un po'' del loro stesso sangue.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (218, 'itIT', 'Temo che i rancori tra i Pietradura e i Maclure possano nuocere alla storia d''amore nata tra Tommy Joe e Maybell, e in tempi come questi, con brutte notizie e voci di guerra che incombono su di noi, i giovani e l''amore vanno difesi.$B$BTi chiedo di usare le tue abilità per creare una pozione o un elisir in grado di aiutare questi giovani piccioncini a coronare il loro sogno.$B$BGrazie, William, e ricordati di venirmi a trovare quando hai del tempo libero. Ci faremo qualche risata ripensando al passato.$B$BMildred') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (288, 'itIT', 'Capitano dei Guardaboschi Alleria Ventolesto$B$BNota Cacciatrice di Troll di Quel''Thalas. Esploratrice Capo e Spia della Spedizione dell''Alleanza che marciò su Draenor, la terra natale degli Orchi. Data per morta.$B$BIl tuo cuore è volato dritto come una freccia nel vento, sorella. Eri la migliore del nostro Ordine e la più amata della nostra razza.$B$BSylvanas Ventolesto, Generale dei Guardaboschi di Quel''Thalas') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (292, 'itIT', 'Qui riposa Uther l''Araldo della Luce$BPrimo Paladino, Fondatore dell''Ordine della Mano d''Argento$B$BUther è vissuto e morto per difendere il regno di Lordaeron. Anche se fu tradito dal suo studente prediletto, crediamo che il suo spirito continui a vivere. Egli veglia su di noi anche ora che le tenebre si avvicinano alla nostra terra devastata. La sua è la luce di tutta l''umanità e finché seguiremo il suo esempio, non svanirà mai.$B$BAnonimo') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (350, 'itIT', 'La Console di Comando del Samoflago può essere usata per regolare automaticamente l''afflusso di carburanti, gas, liquidi e i relativi macchinari. Una volta terminata la configurazione iniziale, dovrebbe funzionare senza problemi e richiedere una manutenzione minima.$B$BBreve elenco dei componenti della Console di Comando (da sinistra a destra)$B$BI. Leva di accensione$B$BTirandola si attiva il Samoflago. Il meccanismo di controllo non si disattiverà automaticamente quando la leva viene rimessa in posizione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (355, 'itIT', 'Questo servirà semplicemente ad avviare il processo di raffreddamento. Una volta completato, ci vorranno da uno a due minuti circa (a seconda della situazione) perché si spenga.$B$BIMPORTANTE: la leva dell''accensione può essere azionata solo quando le tre valvole di controllo sul macchinario sono state disattivate. Queste valvole possono essere chiuse in qualsiasi ordine.$B$BLa prima, posta alla base della grande ciminiera verticale, è la VALVOLA DI CONTROLLO PRINCIPALE.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (356, 'itIT', 'Poi c''è la VALVOLA DI CONTROLLO DEL CARBURANTE, situata sul grosso condotto che parte dai serbatoi del carburante (ce ne dovrebbero essere tre) e arriva alla ciminiera. Infine, c''è la VALVOLA DI REGOLAZIONE, posta su uno dei due grossi serbatoi cilindrici (quello più in basso) che arrivano alla ciminiera.$B$BII. Indicatori del carburante$B$BMostrano la pressione attuale nel primo, secondo e terzo serbatoio per il carburante.$B$BIII. Indicatore di flusso$B$BMostra la portata attuale all''interno del sistema.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (357, 'itIT', 'IV. Controlli del flusso$B$BPermettono di aumentare o diminuire la portata. Viene controllata automaticamente dal meccanismo di controllo del Samoflago.$B$BV. Indicatore della temperatura$B$BMostra la temperatura di funzionamento generale del sistema.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (627, 'itIT', 'La devastante Seconda Guerra contro l''Orda degli Orchi lasciò l''Alleanza di Lordaeron in uno stato di confusione e smarrimento. Gli Orchi assetati di sangue, guidati dal potente Capoguerra Orgrim Martelfato, non solo seminarono distruzione nelle terre dei Nani di Khaz Modan, ma misero a ferro e fuoco anche molte province centrali di Lordaeron. Gli implacabili Orchi riuscirono addirittura a devastare il regno remoto degli Elfi di Quel''Thalas prima che la loro furia venisse finalmente arrestata.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (628, 'itIT', 'Gli eserciti dell''Alleanza, guidati da Ser Anduin Lothar, Uther l''Araldo della Luce e dall''Ammiraglio Daelin Marefiero respinsero gli Orchi a sud, nelle terre devastate di Azeroth, il primo regno a cadere sotto il feroce massacro degli Orchi.$B$BLe forze dell''Alleanza al comando di Ser Lothar riuscirono a cacciare i clan di Martelfato da Lordaeron e a rispedirli nei territori di Azeroth controllati dagli Orchi. Le forze di Lothar circondarono la cittadella vulcanica dei Bastioni di Roccianera e la assediarono.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (629, 'itIT', 'Nell''ultimo, disperato, tentativo di resistere, Martelfato e i suoi luogotenenti caricarono coraggiosamente dai Bastioni e si scontrarono con i Paladini di Lothar al centro delle Steppe Ardenti. Martelfato e Lothar si affrontarono in una battaglia epica, che lasciò entrambi i contendenti esausti e feriti. Anche se Martelfato riuscì a uccidere a fatica Lothar, la morte del grande eroe non ebbe l''effetto che sperava.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (630, 'itIT', 'Turalyon, il più fidato tra i luogotenenti di Lothar, prese il suo scudo macchiato di sangue e chiamò a raccolta i propri fratelli addolorati per contrattaccare. Unite sotto gli stendardi stracciati di Lordaeron e Azeroth, le truppe di Turalyon massacrarono il grosso delle forze rimaste di Martelfato al termine di un''aspra battaglia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (631, 'itIT', 'Agli Orchi superstiti non rimase altro da fare che fuggire verso il loro ultimo bastione: il Portale Oscuro.$B$BTuralyon e i suoi guerrieri inseguirono gli Orchi in fuga attraverso la Palude del Dolore fino alle Terre Devastate dove si trovava il Portale Oscuro. Lì, di fronte al gigantesco portale, le forze dell''Orda e dell''Alleanza si affrontarono in quella che fu l''ultima e più sanguinosa battaglia della Seconda Guerra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (632, 'itIT', 'Sovrastati per numero e resi pazzi dalla maledizione della loro brama di sangue, gli Orchi caddero di fronte all''ira dell''Alleanza. Martelfato fu fatto prigioniero e scortato a Lordaeron, mentre i suoi clan sciolti furono radunati e condotti a nord.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (690, 'itIT', 'La parola TRADITORE è scarabocchiata sull''epitaffio finemente inciso che recita:
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1011, 'itIT', 'Ho trovato un metodo per accedere alla Sala di Khaz''mul! Prendi il Medaglione di Gni''kiv dal mio forziere.$B$BSconfiggi il Trogg Revelosh nella sala prima della stanza delle mappe e recupera la Staffa di Tsol. Unisci il medaglione alla staffa per formare il Bastone della Preistoria.$B$BUsa il bastone nella stanza delle mappe per aprire la porta che conduce alla Sala di Khaz''mul. Fa'' come ti ho detto e la Sala sarà tua!$B$BBaelog') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1091, 'itIT', 'Il Martello di Zul''farrak$B$BPer creare il Martello di Zul''farrak bisogna viaggiare fino all''Altare di Zul e ottenere il martello sacro da un Guardiano dei Troll.$B$BSuccessivamente è necessario portarlo presso l''altare in cima alla città dei Troll di Jintha''alor. Utilizzando il martello sacro sull''altare esso verrà infuso di potere, trasformandosi nel Martello di Zul''farrak.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1313, 'itIT', 'A cosa stavo pensando? O forse sarebbe meglio dire: a che mi serve scrivere nu biglietto mentre mi trovo prigioniero nello stomaco di nu gigante? Sono entrambe belle domande, per i quali però nun tengo na risposta pronta...
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1314, 'itIT', 'Se qualche forma di vita intelligente dovesse riuscire a trovare chisto biglietto, si faccia chesta domanda: "Perché farsi notare in presenza di giganti alti dieci metri?"
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1433, 'itIT', 'Uggel Mazzamano
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1731, 'itIT', 'Qui giace Re Terenas Menethil II, ultimo vero Re di Lordaeron.$B$BLe sue imprese furono grandiose, il suo regno lungo e la sua morte assurda.$B$B"Possa il padre riposare senza colpe per le azioni del figlio. Possa la corona insanguinata rimanere perduta e dimenticata."') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1787, 'itIT', 'Ignari dell''intenzione di Sargeras di distruggere le loro innumerevoli opere, i Titani continuarono a spostarsi da un mondo all''altro, modellando e ordinando ogni pianeta come ritenevano più opportuno. Durante il loro viaggio giunsero su un piccolo mondo che in seguito sarebbe stato ribattezzato Azeroth dai suoi abitanti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1788, 'itIT', 'Mentre i Titani si facevano largo attraverso il paesaggio primordiale, si imbatterono in numerose creature elementali ostili. Questi elementali, che adoravano una razza di esseri incredibilmente malvagi noti solo come gli Dei Antichi, giurarono di scacciare i Titani e proteggere il loro mondo dal tocco metallico degli invasori.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1789, 'itIT', 'Turbato dalla malvagità degli Dei Antichi, il Pantheon mosse guerra contro gli elementali e i loro signori oscuri. Le armate degli Dei Antichi erano guidate dai più forti luogotenenti elementali: Ragnaros il Signore del Fuoco, Therazane la Madre Roccia, Al''Akir il Signore del Vento e Neptulon il Cacciatore delle Maree.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1790, 'itIT', 'Le loro forze caotiche imperversarono sulla faccia del mondo e si scontrarono con gli enormi Titani. Anche se gli elementali disponevano di un potere sconfinato, le loro forze combinate non riuscirono a fermare i possenti Titani. I Signori Elementali caddero uno dopo l''altro e i loro eserciti furono dispersi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1791, 'itIT', 'Il Pantheon distrusse le roccaforti degli Dei Antichi e incatenò le cinque divinità malvagie sotto la superficie del mondo. Senza il potere degli Dei Antichi a tenere legati al mondo fisico i loro spiriti furenti, gli elementali furono banditi in un piano abissale, destinati a lottare tra loro per l''eternità. Con l''allontanamento degli elementali, la natura si placò e il mondo trovò un equilibrio di pace e armonia. I Titani videro che la minaccia era stata contenuta e si misero all''opera.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1792, 'itIT', 'I Titani conferirono dei poteri a diverse razze per aiutarli a modellare il mondo. Affinché riuscissero a scavare le grotte senza fondo sottoterra, i Titani realizzarono delle creature di roccia simili ai Nani. Per aiutarle a prosciugare i mari e alzare la terra dal letto marino, crearono gli enormi ma pacifici Giganti del Mare. Per molti anni i Titani spostarono e plasmarono la terra, fino a ottenere un continente perfetto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1793, 'itIT', 'Al centro del continente fu creato un lago di energie scintillanti, ribattezzato Pozzo dell''Eternità. Le sue potenti energie avrebbero nutrito le fondamenta del mondo e permesso alla vita di attecchire sul suolo fertile. Con il passare del tempo piante, animali, mostri e creature di ogni genere iniziarono a comparire sul continente primordiale.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1794, 'itIT', 'Al tramonto dell''ultimo giorno della loro creazione, i Titani chiamarono il continente Kalimdor: "la terra della luce stellare eterna".') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1795, 'itIT', 'Soddisfatti per ciò che avevano realizzato, i Titani si prepararono a lasciare Azeroth. Prima di partire, incaricarono però le più grandi creature del mondo di sorvegliare Kalimdor, per impedire che qualsiasi entità potesse minacciarne la sua perfetta tranquillità. A quell''epoca c''erano molti Stormi dei Draghi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1796, 'itIT', 'Cinque stormi in particolare dominavano sui propri fratelli. I Titani scelsero proprio loro per guidare la crescita del mondo. I più grandi membri del Pantheon donarono una parte del loro potere a ciascun capo degli stormi. Questi maestosi draghi (come riportato sotto) presero il nome di Grandi Aspetti o Aspetti del Drago.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1797, 'itIT', 'Aman''thul, il Sommo Padre del Pantheon, donò parte del proprio potere cosmico all''enorme Drago di Bronzo Nozdormu, per proteggere il tempo e presidiare i sentieri del fato in continuo mutamento. L''eroico e rispettabile Nozdormu prese il nome di Eterno.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1798, 'itIT', 'Eonar, Titano a protezione di tutta la vita, donò parte del proprio potere al leviatano rosso, Alexstrasza. Da allora Alexstrasza assunse il nome di Protettrice della Vita e si impegnò a difendere tutte le creature viventi del mondo. Grazie alla sua suprema saggezza e all''infinita compassione per tutti gli esseri viventi, Alexstrasza fu incoronata Regina dei Draghi e le fu concessa la sovranità sulla sua razza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1799, 'itIT', 'Eonar benedisse inoltre la sorella più giovane di Alexstrasza, l''agile Drago Verde Ysera, conferendole parte dell''influenza della natura. Ysera cadde in un sonno eterno, vincolata al Sogno della Creazione. Conosciuta come la Sognatrice, avrebbe vegliato sulle crescenti regioni selvagge del mondo dal suo reame verdeggiante, il Sogno di Smeraldo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1800, 'itIT', 'Norgannon, custode delle conoscenze dei Titani e grande Mago, donò una parte del proprio immenso potere al Drago Blu Malygos. Da lì in avanti Malygos cambiò nome in Plasmamagie, il guardiano della magia e dei segreti arcani.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1801, 'itIT', 'Khaz''goroth, il Titano che aveva modellato e forgiato il mondo, donò parte del proprio vasto potere a Neltharion, il grande Dragone Nero dal cuore nobile, ribattezzato in seguito Custode della Terra, al quale fu concessa la sovranità sulla terra e sugli abissi del mondo. Egli incarnava la forza del mondo e fu il più grande sostenitore di Alexstrasza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1802, 'itIT', 'Dopo aver assegnato questi poteri ai Cinque Aspetti, i Titani abbandonarono per sempre Azeroth, certi che i draghi l''avrebbero protetta al posto loro. Purtroppo, fu solo questione di tempo prima che Sargeras venisse a sapere dell''esistenza del nuovo mondo...') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1803, 'itIT', 'L''uso sconsiderato della magia da parte degli Alti Nobili inviò onde d''energia dal Pozzo dell''Eternità fino alla Grande Oscurità. Sargeras, il "Grande Nemico di tutti gli esseri viventi", il "Distruttore di Mondi", percepì le potenti onde e fu attirato nel loro lontano luogo d''origine.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1804, 'itIT', 'Spiando il mondo primordiale di Azeroth e avvertendo le energie infinite del Pozzo dell''Eternità, Sargeras fu consumato da una brama insaziabile. Il grande dio oscuro del Vuoto Sconosciuto decise di distruggere il giovane mondo e reclamarne le energie per sé.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1805, 'itIT', 'Sargeras radunò la sua vasta Legione Infuocata e si diresse verso l''ignaro mondo di Azeroth. La Legione era formata da un milione di demoni urlanti, provenienti dagli angoli più remoti dell''universo, che avevano sete di conquista. I luogotenenti di Sargeras, Archimonde il Profanatore e Mannoroth il Distruttore, prepararono i loro servitori infernali per l''attacco.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1806, 'itIT', 'La Regina Azshara, travolta dagli effetti della sua stessa magia, cadde vittima del potere di Sargeras e accettò di concedergli l''accesso al suo mondo. Anche i suoi servitori Alti Nobili si arresero all''inevitabile corruzione della magia e iniziarono ad adorare Sargeras. Per dimostrare la loro lealtà verso la Legione, gli Alti Nobili aiutarono la loro regina ad aprire un enorme portale turbinante negli abissi del Pozzo dell''Eternità.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1807, 'itIT', 'Una volta completati i preparativi, Sargeras diede inizio all''invasione di Azeroth. I guerrieri demoni della Legione Infuocata si riversarono nel mondo attraverso il Pozzo dell''Eternità e presero d''assedio le città addormentate degli Elfi della Notte. Guidata da Archimonde e Mannoroth, la Legione imperversò per le terre di Kalimdor, lasciando soltanto cenere e distruzione al suo passaggio.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1808, 'itIT', 'Gli stregoni demoni evocarono Infernali che si abbatterono come meteoriti sulle bellissime guglie dei templi di Kalimdor. Un gruppo di assassini assetati di sangue noti come Demoni Guardiani marciarono per i campi di Kalimdor, massacrando tutti coloro che incontravano. Branchi selvaggi di Vilsegugi demoniaci saccheggiarono indisturbati le campagne. Nonostante i coraggiosi Guerrieri Kaldorei fossero intervenuti tempestivamente per difendere la loro antica terra natale, furono costretti a cedere terreno, metro dopo metro, di fronte all''inesorabile avanzata della Legione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1809, 'itIT', 'Toccò a Malfurion Grantempesta cercare aiuto per il proprio popolo. Grantempesta, il cui fratello Illidan esercitava la magia degli Alti Nobili, era esasperato dalla crescente corruzione nell''alto ceto. Dopo aver convinto Illidan ad abbandonare la sua pericolosa ossessione, Malfurion partì in cerca di Cenarius per organizzare una resistenza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1810, 'itIT', 'La splendida giovane sacerdotessa Tyrande accettò di accompagnare i fratelli in nome di Elune. Benché Malfurion e Illidan fossero entrambi innamorati di lei, il cuore di Tyrande apparteneva solo a Malfurion. Illidan era risentito per la storia d''amore di suo fratello con Tyrande, ma sapeva che questo malessere non era niente in confronto al dolore provocatogli dalla sua dipendenza dalla magia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1811, 'itIT', 'Illidan, sempre più dipendente dalla magia, faticava a controllare la sua brama quasi travolgente di attingere nuovamente alle energie del Pozzo. Grazie al paziente aiuto di Tyrande, riuscì a trattenersi e ad aiutare suo fratello a trovare il semidio Cenarius.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1812, 'itIT', 'Quest''ultimo, che viveva nella sacra Radaluna sul lontano Monte Hyjal, accettò di aiutare gli Elfi della Notte a trovare gli antichi draghi e invocare il loro aiuto. I draghi, capeggiati dal grande leviatano rosso Alexstrasza, acconsentirono a inviare i loro possenti stormi per affrontare i demoni e i loro signori infernali.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1813, 'itIT', 'Cenarius chiamò a raccolta gli spiriti delle foreste incantate: radunò un esercito di antichi uomini albero e lo guidò in un audace assalto terrestre contro la Legione. Mentre gli alleati degli Elfi convergevano sul tempio di Azshara e sul Pozzo dell''Eternità, si scatenò la guerra. Nonostante l''aiuto dei loro nuovi alleati, Malfurion e i suoi compagni si resero conto che la Legione non poteva essere battuta solo con la forza bellica.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1814, 'itIT', 'Mentre intorno alla capitale Azshara infuriava una battaglia di proporzioni epiche, la regina attendeva impaziente l''arrivo di Sargeras. Il Signore della Legione si stava apprestando ad attraversare il Pozzo dell''Eternità e a entrare nel mondo devastato. Quando la sua enorme ombra si avvicinò alla superficie agitata del Pozzo, Azshara radunò i suoi seguaci Alti Nobili più potenti. Solo unendo le loro magie in un unico incantesimo concentrato avrebbero potuto creare un varco abbastanza largo per Sargeras.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1815, 'itIT', 'Con il procedere degli scontri nei campi in fiamme di Kalimdor, si verificò uno sviluppo imprevisto. I dettagli dell''evento sono andati persi col tempo, ma si sa che Neltharion, l''Aspetto della Terra, impazzì durante un combattimento decisivo contro la Legione Infuocata. Cominciò a squarciarsi, mentre le fiamme e la rabbia eruttavano dalla sua corazza scura. Con il nuovo nome di Alamorte, il drago infuocato si rivoltò contro i suoi fratelli e allontanò i cinque stormi dalla battaglia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1816, 'itIT', 'L''improvviso tradimento di Alamorte fu un colpo devastante, dal quale i cinque stormi non riuscirono più a riprendersi. Feriti e sconvolti, Alexstrasza e gli altri nobili draghi furono costretti ad abbandonare i loro alleati mortali. Malfurion e i suoi compagni, sopraffatti numericamente e senza alcuna speranza, sopravvissero a malapena al massacro che seguì.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1817, 'itIT', 'Convinto che il Pozzo dell''Eternità rappresentasse il legame centrale tra i demoni e il mondo fisico, Malfurion insistette per distruggerlo. I suoi compagni, sapendo che il Pozzo era la fonte della loro immortalità e potere, furono terrorizzati al solo pensiero. Eppure Tyrande vide della saggezza nella teoria di Malfurion, così convinse Cenarius e i suoi alleati ad attaccare il tempio di Azshara e trovare un modo per chiudere il Pozzo una volta per tutte.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1828, 'itIT', 'I pochi Elfi della Notte che sopravvissero alla devastante esplosione si riunirono su alcune zattere di fortuna e raggiunsero lentamente le uniche terre in vista. In qualche modo, per la grazia di Elune, Malfurion, Tyrande e Cenarius sopravvissero alla Grande Separazione. Esausti, gli eroi decisero di guidare i superstiti alla ricerca di una nuova casa per il loro popolo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1829, 'itIT', 'Mentre camminavano in silenzio, osservarono le macerie del loro mondo e capirono che erano state le loro passioni a causare quella distruzione. Sargeras e la sua Legione erano stati banditi dal mondo con la distruzione del Pozzo, ma la vittoria di Malfurion e dei suoi compagni era stata conquistata a caro prezzo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1830, 'itIT', 'Molti Alti Nobili sopravvissero al Cataclisma senza subire danni e raggiunsero le coste della nuova terra insieme agli Elfi della Notte. Malfurion non si fidava della natura degli Alti Nobili, ma fu tranquillizzato dal fatto che non potessero più causare danni perché privati delle energie del Pozzo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1831, 'itIT', 'Quando gli Elfi della Notte raggiunsero le coste del loro nuovo mondo, scoprirono che la montagna sacra, il Monte Hyjal, aveva resistito alla catastrofe. Ansiosi di trovare una nuova dimora, Malfurion e gli Elfi della Notte scalarono i pendii di Hyjal e raggiunsero la sua sommità spazzata dal vento. Discesero poi nella sua conca boscosa fra gli alti picchi della montagna e vi trovarono un piccolo lago tranquillo. Con grande orrore però si accorsero che le sue acque erano state contaminate dalla magia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1832, 'itIT', 'Sopravvissuto alla Grande Separazione, Illidan era giunto sulla sommità del Monte Hyjal molto tempo prima di Malfurion e degli Elfi della Notte. Nel folle tentativo di mantenere il flusso della magia nel mondo, versò nel lago la preziosa acqua del Pozzo dell''Eternità, contenuta in alcune fiale.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1833, 'itIT', 'Le potenti energie del Pozzo si attivarono rapidamente, andando così a creare un nuovo Pozzo dell''Eternità. Credendo che il nuovo Pozzo fosse un dono per le generazioni a venire, Illidan esultò, ma fu scioccato quando venne inseguito da Malfurion. Suo fratello gli spiegò che la magia conteneva in sé i semi del caos e che il suo utilizzo avrebbe inevitabilmente portato alla corruzione e al conflitto. Nonostante tutto, Illidan si rifiutò di rinunciare ai poteri magici.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1834, 'itIT', 'Consapevole delle conseguenze che avrebbero avuto gli sconsiderati progetti di Illidan, Malfurion decise di occuparsi una volta per tutte di suo fratello e della sua sete di potere. Con l''aiuto di Cenarius rinchiuse Illidan in una prigione sotterranea dove sarebbe rimasto fino alla fine dei tempi, incatenato e privo di ogni forza. Per assicurarsi che non fuggisse, Malfurion ordinò alla giovane custode Maiev Cantombroso di diventare il carceriere personale di Illidan.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1835, 'itIT', 'Temendo che la distruzione del nuovo Pozzo potesse provocare un''altra catastrofe, gli Elfi della Notte decisero di lasciarlo dov''era. Malfurion però giurò che nessuno di loro avrebbe mai più fatto ricorso alle arti magiche. Sotto il vigile sguardo di Cenarius iniziarono così a studiare le antiche arti dei Druidi, che avrebbero permesso loro di curare la terra devastata, facendo rinascere le foreste alle pendici del Monte Hyjal.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1836, 'itIT', 'Per molti anni gli Elfi della Notte lavorarono instancabilmente per ricostruire la loro antica terra natale. Si lasciarono alle spalle gli antichi templi distrutti e le strade in rovina ed edificarono nuove dimore fra i verdi alberi e le ombrose colline ai piedi del Monte Hyjal. Col tempo, anche i draghi sopravvissuti alla Grande Separazione riemersero dalle loro dimore segrete.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1837, 'itIT', 'Alexstrasza la Rossa, Ysera la Verde e Nozdormu il Bronzeo discesero sulle tranquille terre dei Druidi e vegliarono sui frutti del lavoro degli Elfi della Notte. Divenuto ormai un Arcidruido dall''immenso potere, Malfurion accolse i possenti draghi e raccontò loro della creazione del nuovo Pozzo dell''Eternità.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1838, 'itIT', 'I grandi draghi furono allarmati da quella notizia e dissero che finché il Pozzo esisteva la Legione avrebbe potuto fare ritorno per attaccare nuovamente il mondo. Malfurion e i tre draghi strinsero allora un patto per garantire la sicurezza del Pozzo e fare in modo che la Legione Infuocata non potesse mai più recare alcun danno.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1839, 'itIT', 'Alexstrasza la Protettrice della Vita mise una ghianda incantata al centro del Pozzo dell''Eternità che, attivata dalle potenti acque magiche, diede subito vita a un albero colossale. Le sue radici crebbero dalle acque del Pozzo e la sua verde chioma sembrò arrivare a lambire il cielo stesso.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1840, 'itIT', 'Quell''enorme albero sarebbe divenuto il simbolo eterno del legame degli Elfi della Notte con la natura e le sue energie vitali e con il passare del tempo avrebbero guarito il mondo intero. Gli Elfi della Notte diedero all''Albero del Mondo il nuovo nome di Nordrassil, che nella loro lingua significa "Corona dei Cieli".') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1841, 'itIT', 'Nozdormu l''Eterno lanciò un incantesimo sull''Albero del Mondo. Finché fosse esistito il colossale albero, gli Elfi della Notte non sarebbero invecchiati, né si sarebbero ammalati.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1842, 'itIT', 'Anche Ysera la Sognatrice incantò l''Albero del Mondo collegandolo al proprio reame: la dimensione eterea conosciuta come Sogno di Smeraldo, una vasta landa spirituale in costante mutamento situata al di fuori del mondo fisico. Tramite il Sogno di Smeraldo, Ysera regolò il flusso vitale della natura e il percorso evolutivo dell''intero mondo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1843, 'itIT', 'I Druidi degli Elfi della Notte, fra i quali lo stesso Malfurion, strinsero un legame con il Sogno tramite l''Albero del Mondo. Siglando il mistico patto, essi acconsentirono di dormire per lunghi secoli, cosicché i loro spiriti potessero vagare per le infinite Vie dei Sogni di Ysera. Anche se i Druidi non erano felici al pensiero di trascorrere una parte della loro vita in ibernazione, accettarono di onorare l''accordo con Ysera.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1844, 'itIT', 'Con il passare dei secoli, la nuova società degli Elfi della Notte divenne forte e si estese per l''intera foresta che essi chiamavano Valtetra. Molte delle creature e delle specie esistenti prima della Separazione, come Mezzorsi e Verrospino, riapparvero e crebbero di numero. Sotto la guida benevola dei Druidi gli Elfi della Notte vissero un''era di pace e tranquillità senza precedenti sotto le stelle.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1845, 'itIT', 'I discendenti degli Alti Nobili sopravvissuti però divennero sempre più irrequieti. Come già Illidan prima di loro, caddero vittima del rimpianto per la perdita della loro magia e così furono tentati di attingere alle energie del Pozzo dell''Eternità per riprendere la pratica magica. Dath''Remar l''Insolente si impose come guida degli Alti Nobili e iniziò a deridere pubblicamente i Druidi, chiamandoli codardi per via del rifiuto di utilizzare la magia che, secondo lui, era loro di diritto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1846, 'itIT', 'Malfurion e i Druidi respinsero le argomentazioni di Dath''Remar e ammonirono gli Alti Nobili: qualsiasi ricorso alla magia sarebbe stato punito con la morte. In un avventato e maldestro tentativo di convincere i Druidi a mutare la legge, Dath''Remar e i suoi seguaci finirono per scatenare una tremenda tempesta magica su Valtetra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1847, 'itIT', 'I Druidi non ebbero il coraggio di mettere a morte così tanti fratelli e così decisero di esiliare gli Alti Nobili ribelli dalle loro terre. Lieti finalmente di essere liberi dai loro simili, Dath''Remar e i suoi compagni si imbarcarono su vascelli costruiti per l''occasione e salparono. Anche se nessuno di loro sapeva ciò che li attendeva oltre la furia del Maelstrom, erano ansiosi di fondare una propria patria dove poter praticare liberamente le arti magiche.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1848, 'itIT', 'Gli Alti Nobili, o Quel''dorei, come Azshara li aveva definiti nelle ere passate, sbarcarono infine in una terra a oriente che gli uomini avrebbero chiamato Lordaeron. Qui decisero di fondare il loro regno magico, Quel''Thalas, respingendo precetti degli Elfi della Notte quali l''adorazione della Luna e le attività notturne. Da allora essi vissero alla luce del sole assumendo il nome di Alti Elfi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1854, 'itIT', 'Gli Alti Elfi guidati da Dath''Remar si lasciarono Kalimdor alle spalle, sfidando le tempeste del Maelstrom. Le loro flotte percorsero per molti anni ciò che restava del mondo, scoprendo misteri e regni perduti. Dath''Remar, che aveva assunto il nome di Solealto (o "Colui che cammina nel giorno"), era alla ricerca di luoghi in cui il potere della faglia fosse abbastanza grande per creare la nuova dimora della sua gente.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1855, 'itIT', 'La sua flotta raggiunse infine le rive del regno che un giorno gli uomini avrebbero chiamato Lordaeron. Nell''entroterra gli Alti Elfi fondarono un insediamento in mezzo alle Radure di Tirisfal. Dopo alcuni anni, molti di loro iniziarono a dare segni di follia: si pensò che nel sottosuolo giacesse qualcosa di malvagio, ma nessuno riuscì mai a provare questa diceria. Gli Alti Elfi si spostarono nuovamente verso nord, in cerca di un''altra terra ricca di energie della faglia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1856, 'itIT', 'Mentre gli Alti Elfi attraversavano le aspre terre montagnose di Lordaeron, il loro viaggio divenne sempre più pericoloso. Disgiunti dalle energie vitali del Pozzo dell''Eternità, molti di loro si ammalarono per la rigidezza del clima o morirono di stenti. Il cambiamento più devastante per loro fu però la perdita dell''immortalità e dell''immunità agli elementi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1857, 'itIT', 'La loro statura si ridusse, mentre la pelle perse il caratteristico colore viola. Nonostante l''ostilità dell''ambiente, incontrarono strane creature mai viste prima a Kalimdor: inoltre si imbatterono in tribù di Umani primitivi che cacciavano in quelle antiche foreste. La minaccia più diretta e seria che dovettero affrontare era però rappresentata dai voraci e astuti Troll delle Foreste di Zul''aman.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1858, 'itIT', 'Questi Troll dalla pelle muschiata erano in grado di rigenerare gli arti mozzati e di curare anche le più gravi ferite: purtroppo erano anche una razza primitiva e malvagia. L''Impero degli Amani occupava buona parte delle terre settentrionali di Lordaeron e i Troll combatterono duramente per tenere gli stranieri fuori dai loro confini. Gli Elfi svilupparono una profonda avversione nei confronti di questi feroci nemici, uccidendoli a vista non appena ne avevano l''occasione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1859, 'itIT', 'Dopo moltissimi anni, gli Alti Elfi riuscirono a trovare una terra che ricordava loro Kalimdor. Nel cuore delle foreste settentrionali del continente fondarono il Regno di Quel''Thalas e giurarono di creare un potente impero che sarebbe stato in grado di oscurare quello dei loro cugini Kaldorei. Purtroppo ben presto scoprirono che Quel''Thalas sorgeva sui resti di un''antica città sacra dei Troll. Di lì a poco i Troll iniziarono ad attaccare gli insediamenti elfici in massa.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1860, 'itIT', 'Decisi a non abbandonare la loro nuova terra, gli ostinati Elfi utilizzarono la magia che avevano portato con sé dal Pozzo dell''Eternità per tenere a bada i selvaggi Troll. Sotto la guida di Dath''Remar sconfissero i guerrieri Amani, sebbene il numero di questi fosse dieci volte superiore. Alcuni Elfi, memori degli antichi avvertimenti dei Kaldorei, espressero il timore che l''uso della magia potesse richiamare l''attenzione della Legione Infuocata in esilio.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1861, 'itIT', 'Per questo decisero di celare le proprie terre utilizzando una barriera protettiva che avrebbe comunque consentito l''utilizzo dei loro incantesimi. Essi realizzarono così delle Pietre Runiche in diversi punti intorno a Quel''Thalas, creando in questo modo una barriera magica. Le Pietre Runiche non solo nascosero la magia degli Elfi alle minacce extra-dimensionali, ma servirono anche a terrorizzare i superstiziosi Troll.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1862, 'itIT', 'Con il passare del tempo, Quel''Thalas divenne un fulgido monumento all''impegno degli Alti Elfi e alla loro maestria nell''uso della magia. I suoi splendidi palazzi furono edificati con lo stesso stile architettonico delle antiche sale di Kalimdor e intessuti nella topografia naturale del territorio. Quel''Thalas divenne infine il gioiello splendente che gli Elfi avevano a lungo sognato.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1863, 'itIT', 'Venne fondato il Concilio di Lunargenta come organo direttivo di Quel''Thalas, anche se la dinastia Solealto mantenne per sé un certo potere politico. Composto da sette dei principali signori degli Alti Elfi, il Concilio operava per garantire la sicurezza delle terre e delle genti elfiche. Circondati dalla barriera protettiva, gli Alti Elfi non ascoltarono gli antichi ammonimenti dei Kaldorei e continuarono a usare la magia in ogni aspetto della loro vita.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1864, 'itIT', 'Per quasi quattromila anni gli Alti Elfi vissero in pace nella sicurezza del loro regno isolato. I vendicativi Troll però non si ritenevano certo sconfitti: complottarono nelle profondità delle foreste, attendendo di crescere fino a raggiungere un numero sufficiente. Infine, uno sconfinato esercito di Troll attaccò dalle ombre dei boschi, stringendo nuovamente d''assedio le guglie lucenti di Quel''Thalas.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1892, 'itIT', 'Nei tempi antichi, dopo la partenza dei Titani da Azeroth, i loro figli, conosciuti come Terrigeni, continuarono a modificare e sorvegliare i più profondi recessi del mondo. Sostanzialmente disinteressati alle azioni delle razze della superficie, i Terrigeni erano soddisfatti della loro vita nelle oscurità del sottosuolo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1893, 'itIT', 'Quando il mondo venne scosso dall''implosione del Pozzo dell''Eternità, le conseguenze per i Terrigeni furono devastanti. Afflitti dal dolore della terra stessa, furono privati della propria identità e si rinchiusero nelle camere di pietra dove un tempo erano stati creati. Uldaman, Uldum, Ulduar... Quelli erano i nomi delle antiche città dei Titani che avevano dato loro i natali. Sepolti in profondità, i Terrigeni riposarono in pace per quasi ottomila anni.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1894, 'itIT', 'Anche se non è chiaro per quale motivo si svegliarono, un giorno i Terrigeni di Uldaman uscirono dal loro esilio autoimposto. Quei Terrigeni scoprirono di essere mutati sensibilmente durante l''ibernazione: le loro membra rocciose si erano ammorbidite, cedendo il passo a carne e pelle, e i loro poteri su pietra e terra erano svaniti. Erano divenuti creature mortali.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1895, 'itIT', 'Dopo aver assunto il nome di Nani, gli ultimi Terrigeni uscirono dalle sale di Uldaman e si avventurarono nel mondo. Sempre attirati dalla sicurezza e dalle meraviglie delle caverne più profonde, fondarono un grande regno sotto la montagna più alta.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1896, 'itIT', 'Le loro terre furono chiamate Khaz Modan, o "Montagna di Khaz", in onore di Khaz''goroth, il Titano che ha plasmato il mondo. Per realizzare un altare per il loro padre Titano, i Nani crearono un''enorme forgia nel cuore della montagna. La città che crebbe intorno a quel luogo fu chiamata Forgiardente.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1897, 'itIT', 'I Nani, affascinati per via della loro natura dalla lavorazione delle gemme e della pietra, iniziarono subito a scavare le montagne circostanti in cerca di ricchezze e minerali preziosi. Soddisfatti della loro vita sotterranea, si isolarono completamente dalle attività dei loro vicini: gli abitanti della superficie.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1906, 'itIT', 'Mentre le sette nazioni umane erano al centro di questioni politiche e rivalità, i Guardiani continuarono a vegliare per impedire il sopraggiungere del caos. In molti si succedettero negli anni, ma solo un Guardiano alla volta poteva incarnare i poteri magici di Tirisfal. Uno degli ultimi Guardiani di quell''era seppe distinguersi come valorosa guerriera contro l''ombra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1907, 'itIT', 'Aegwynn, una fiera ragazza umana, seppe conquistare i favori dell''Ordine e ottenne la carica di Guardiano. Si impegnò a fondo per rintracciare ed eliminare i demoni, ovunque essi si annidassero, ma si ritrovò spesso a mettere in dubbio l''autorità del Concilio di Tirisfal, in prevalenza maschile.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1908, 'itIT', 'Secondo Aegwynn, gli antichi Elfi e gli anziani Umani che sedevano nel Concilio erano troppo rigidi nel loro modo di pensare e non avevano il coraggio di tentare una mossa risolutiva nella lotta contro il caos. Infastidita da lunghe discussioni e dibattiti, Aegwynn non vedeva l''ora di dimostrare il proprio valore ai suoi pari e ai superiori: per questo in diverse occasioni scelse di seguire la via del coraggio piuttosto che quella della saggezza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1909, 'itIT', 'Con il crescere della sua maestria nell''uso dei poteri cosmici di Tirisfal, Aegwynn prese coscienza dell''esistenza di diversi demoni potenti che tormentavano il gelido continente di Nordania. Viaggiando fino al lontano nord, Aegwynn riuscì a scovare i demoni fra le montagne: là scoprì che essi stavano dando la caccia a uno degli ultimi stormi per impossessarsi dei poteri magici innati delle creature.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1910, 'itIT', 'I possenti draghi, che si erano ritirati di fronte alla costante avanzata della società dei mortali, avevano trovato un temibile nemico nella magia oscura della Legione. Aegwynn affrontò i demoni e con l''aiuto dei nobili draghi riuscì ad annientarli. Tuttavia, quando anche l''ultimo demone scomparve dal mondo mortale, una violenta tempesta si abbatté sulle terre del nord.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1911, 'itIT', 'Un enorme e tenebroso viso apparve nel cielo sopra Nordania. Sargeras, il demoniaco sovrano e signore della Legione Infuocata, comparve dinanzi a Aegwynn, rifulgendo di energia infernale. Egli disse alla giovane Guardiana che il tempo di Tirisfal stava per giungere al termine e che il mondo avrebbe presto conosciuto il giogo della Legione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1912, 'itIT', 'La fiera Aegwynn, credendo di essere in grado di sfidare il minaccioso figuro, scatenò il suo potere contro l''avatar di Sargeras. Con una sconcertante facilità, Aegwynn riuscì a sconfiggere il signore dei demoni, uccidendo la sua forma fisica. Temendo che lo spirito di Sargeras potesse perdurare, ingenuamente Aegwynn rinchiuse ciò che restava del suo corpo in una delle antiche sale di Kalimdor, finita sul fondo del mare con il collasso del Pozzo dell''Eternità.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1913, 'itIT', 'Aegwynn non poteva sapere che, agendo in quel modo, aveva fatto esattamente ciò che Sargeras voleva. La Guardiana aveva involontariamente condannato il mondo intero, perché nell''istante in cui le spoglie mortali di Sargeras cadevano, il demone aveva trasferito il suo spirito nel corpo della stessa Aegwynn. Senza che la giovane Guardiana se ne accorgesse, Sargeras rimase per molti anni nascosto nei più oscuri meandri della sua anima.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1914, 'itIT', 'I Nani della Montagna di Forgiardente vissero in pace per molti secoli, ma la loro società divenne infine troppo grande per essere contenuta entro le loro città montane. Anche se il Gran Sovrano, Modimus Forgiamara, governava sui suoi sudditi con giustizia e saggezza, sorsero tre potenti fazioni nella società dei Nani.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1915, 'itIT', 'Il Clan Barbabronzea, guidato dal Thane Madoran Barbabronzea, manteneva stretti legami con il Gran Sovrano e si ergeva a difensore delle tradizioni di Forgiardente. Il Clan Granmartello, guidato dal Thane Khardros Granmartello, si insediò tra le colline e nei dirupi alla base della montagna, cercando di accrescere la propria influenza all''interno della città.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1916, 'itIT', 'La terza fazione, il Clan Ferroscuro, aveva al proprio comando il Thane Occultista Thaurissan. I Ferroscuro si nascondevano nelle ombre più oscure sotto la montagna, complottando contro i Barbabronzea e i Granmartello.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1917, 'itIT', 'Per un certo periodo, le tre fazioni riuscirono a mantenere un''instabile pace, ma quando il Gran Sovrano Forgiamara morì di vecchiaia, le tensioni esplosero. I tre clan presero a combattere per il controllo di Forgiardente e la guerra civile dei Nani divampò per molti anni nel sottosuolo, fino a quando i Barbabronzea, forti del loro grande esercito, riuscirono a bandire dalla montagna i Granmartello e i Ferroscuro.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1918, 'itIT', 'Khardros e i suoi Guerrieri Granmartello viaggiarono verso nord, attraverso i portali di Dun Algaz, dove fondarono un fiorente regno all''interno del picco di Grim Batol. Le cose non andarono altrettanto bene per Thaurissan e i suoi Ferroscuro: umiliati e infuriati per la sconfitta, giurarono di vendicarsi di Forgiardente. Thaurissan guidò le sue genti a sud, dove fondò una città alla quale diede il proprio nome nella catena delle splendide Montagne Crestarossa.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1919, 'itIT', 'Le nuove ricchezze e il passare degli anni non riuscirono a placare il rancore dei Ferroscuro nei confronti dei loro simili. Un giorno Thaurissan e sua moglie, l''Occultista Modgud, lanciarono un doppio assalto contro Forgiardente e Grim Batol. I Ferroscuro volevano il dominio totale su Khaz Modan.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1920, 'itIT', 'Gli eserciti dei Ferroscuro travolsero le roccaforti degli altri clan e quasi riuscirono a conquistare entrambi i reami. Alla fine però Madoran Barbabronzea guidò il suo clan in una vittoria decisiva contro l''esercito di Thaurissan. Costui allora fuggì insieme ai suoi seguaci, cercando riparo nella sicurezza della propria città, ignaro di quanto avvenuto a Grim Batol, dove l''esercito di Modgud sarebbe stato a sua volta sconfitto da Khardros e dai suoi Guerrieri Granmartello.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1921, 'itIT', 'Affrontando i combattenti nemici, Modgud utilizzò i suoi poteri per gettare nel terrore i loro cuori. Le ombre si mossero al suo comando e oscuri esseri emersero dalle profondità della terra per tormentare i Granmartello nelle loro dimore. Ella riuscì infine a superare le mura, arrivando ad assediare la fortezza. I Granmartello combatterono disperatamente, mentre Khardros stesso vagava per il campo di battaglia, fino a quando riuscì a uccidere la Regina Occultista.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1922, 'itIT', 'Dopo la perdita della loro guida, i Ferroscuro fuggirono dinanzi alla furia dei Granmartello. Si diressero a sud, verso la roccaforte del loro sovrano, ma così facendo si scontrarono con l''esercito di Forgiardente, giunto in aiuto di Grim Batol. Intrappolati fra le due armate, i resti delle forze dei Ferroscuro furono annientati rapidamente.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1923, 'itIT', 'Gli eserciti congiunti di Forgiardente e di Grim Batol si diressero allora verso sud, con l''intenzione di annientare una volta per sempre Thaurissan e i suoi Ferroscuro. Non fecero molta strada: la furia di Thaurissan diede vita a un incantesimo di proporzioni disastrose. Nel tentativo di evocare un servitore sovrannaturale capace di donargli la vittoria, Thaurissan risvegliò antiche forze da tempo sopite sotto il mondo. Con suo grande sgomento, dalle viscere della terra emerse una creatura infinitamente più terribile di quanto egli si aspettasse.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1924, 'itIT', 'Ragnaros il Signore del Fuoco, immortale sovrano di tutti gli Elementali del Fuoco, era stato rinchiuso dai Titani quando il mondo era ancora giovane. Ora, grazie all''evocazione di Thaurissan, Ragnaros era di nuovo libero: la sua apocalittica rinascita distrusse le Montagne Crestarossa, generando un vulcano in perenne attività al centro della devastazione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1925, 'itIT', 'Il vulcano, conosciuto come Massiccio di Roccianera, era fiancheggiato dalla Gorgia Rovente a nord e dalle Steppe Ardenti a sud. Thaurissan era stato ucciso dalle forze che aveva scatenato e i suoi compagni superstiti vennero ridotti in schiavitù da Ragnaros e dai suoi elementali. Ancora oggi, essi vivono nei Bastioni di Roccianera.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1926, 'itIT', 'Re Madoran e Re Khardros, testimoni dell''orrenda devastazione e delle fiamme che avevano avvolto le montagne meridionali, richiamarono i loro eserciti e si affrettarono a tornare nei loro regni, riluttanti ad affrontare la collera di Ragnaros.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1927, 'itIT', 'I Barbabronzea tornarono a Forgiardente e ricostruirono la loro gloriosa città. Anche i Granmartello fecero ritorno alla loro dimora, a Grim Batol, ma la morte di Modgud aveva lasciato un segno di disgrazia nella loro fortezza che risultò essere inabitabile.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1928, 'itIT', 'Il loro cuore era colmo di tristezza per la perdita dell''amata casa. Re Barbabronzea offrì ai Granmartello un luogo dove vivere entro i confini di Forgiardente, ma essi rifiutarono con fermezza. Khardros condusse a nord la sua gente, verso le terre di Lordaeron. Una volta giunti nelle lussureggianti foreste delle Entroterre, i Granmartello fondarono la città di Picco dell''Aquila, iniziando ad avvicinarsi alla natura e arrivando ad addestrare i potenti grifoni di quell''area.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1929, 'itIT', 'Nel tentativo di mantenere vivi i legami con i loro simili, i Nani di Forgiardente costruirono due enormi archi con i quali superare il varco fra Khaz Modan e Lordaeron: il Viadotto di Thandol. Grazie ai reciproci scambi commerciali, i due regni prosperarono. Dopo la morte di Madoran e Khardros, i loro figli ordinarono la costruzione di due enormi statue, in memoria dei padri.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1930, 'itIT', 'Le due statue sarebbero sorte a guardia del passaggio verso le terre del sud, divenute zona vulcanica dopo la rinascita di Ragnaros. Furono un monito per tutti coloro intenzionati ad attaccare i regni dei Nani e un ricordo del prezzo pagato dai Ferroscuro per i loro crimini.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1931, 'itIT', 'I due regni mantennero legami molto stretti per alcuni anni, ma i Granmartello erano stati profondamente cambiati dagli eventi di Grim Batol. Presero a vivere in superficie, sui pendii di Picco dell''Aquila, invece di creare una rete di gallerie sotto la montagna. Le differenti abitudini fra i due unici clan di Nani rimasti portarono infine a un allontanamento.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1951, 'itIT', 'Gli Orchi, sotto il controllo segreto di Gul''dan e del suo Concilio dell''Ombra, divennero sempre più aggressivi. Realizzarono enormi arene nelle quali affinare le loro capacità combattendo in sfide mortali. Durante quel periodo, ci furono comunque alcuni Capoclan che si opposero a ciò che stava avvenendo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1952, 'itIT', 'Uno di questi, Durotan del Clan Lupi Bianchi, mise in guardia gli Orchi dal pericolo rappresentato da odio e furia. Le sue parole rimasero però inascoltate, e furono i Capoclan più potenti, come Grommash Malogrido del Clan Cantaguerra, a divenire i campioni di una nuova era di guerra e dominio.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1953, 'itIT', 'Kil''jaeden sapeva che i clan degli Orchi erano ormai quasi pronti, ma doveva essere certo della loro lealtà assoluta. Così in segreto aveva fatto in modo che il Concilio dell''Ombra evocasse Mannoroth il Distruttore, personificazione della furia e della devastazione. Gul''dan riunì i capi dei vari clan e li convinse che, bevendo il fiero sangue di Mannoroth, sarebbero divenuti invincibili.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1954, 'itIT', 'Guidati da Grommash Malogrido, tutti i Capoclan con l''eccezione di Durotan bevvero, divenendo così per sempre schiavi della Legione Infuocata. Spinti dalla furia di Mannoroth, i Capoclan estesero rapidamente questo vincolo ai loro fratelli ignari.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1955, 'itIT', 'Consumati dalla maledizione della sete di sangue, gli Orchi scatenarono la loro furia su chiunque osasse opporsi a loro. Sentendo che era giunto il momento, Gul''dan unificò i diversi clan in un''unica, inarrestabile Orda.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1956, 'itIT', 'Sapendo che i diversi Capoclan, come Malogrido e Orgrim Martelfato, avrebbero lottato incessantemente per la supremazia, Gul''dan nominò un Capoguerra fantoccio a capo dell''Orda. Manonera il Distruttore, un Signore della Guerra particolarmente crudele, fu il prescelto per questo ruolo. Sotto il comando di Manonera, l''Orda sferrò la prima offensiva contro i Draenei.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1957, 'itIT', 'In pochi mesi, l''Orda massacrò quasi tutti i Draenei di Draenor. Soltanto alcuni gruppi di superstiti riuscirono a sfuggire alla terrificante furia degli Orchi. Inebriato dalla vittoria, Gul''dan si beò del potere e della forza dell''Orda, eppure egli sapeva che, senza alcun nemico da combattere, presto l''Orda si sarebbe consumata in infiniti scontri intestini, spinta dalla sua implacabile brama di sangue.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1958, 'itIT', 'Kil''jaeden vide che l''Orda era ormai pronta. Gli Orchi erano divenuti l''arma migliore della Legione Infuocata. A quel punto l''astuto demone informò il suo signore Sargeras, che si disse d''accordo con lui: il tempo della vendetta era finalmente giunto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1959, 'itIT', 'Mentre Kil''jaeden preparava l''Orda per l''invasione di Azeroth, Medivh continuava a lottare contro Sargeras per riottenere il controllo della propria anima. Re Llane, il nobile sovrano di Roccavento, si rese conto dell''oscuro conflitto che gravava sullo spirito del suo vecchio amico.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1960, 'itIT', 'Espresse così le sue preoccupazioni ad Anduin Lothar, ultimo discendente della casata Arathi, che aveva nominato proprio Tenente. Ma nessuno dei due poteva immaginare quali orrori avrebbe causato l''inarrestabile discesa di Medivh verso la follia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1961, 'itIT', 'Come incentivo finale, Sargeras promise di donare poteri illimitati a Gul''dan se egli avesse accettato di guidare l''Orda contro Azeroth. Attraverso Medivh, Sargeras disse allo Stregone che avrebbe potuto divenire un dio se fosse riuscito a trovare la tomba sommersa dove la Guardiana Aegwynn aveva sepolto i resti del corpo di Sargeras più di mille anni prima.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1962, 'itIT', 'Gul''dan accettò e decise che, dopo aver ucciso tutti gli abitanti di Azeroth, si sarebbe messo in cerca della leggendaria tomba per reclamare la sua ricompensa. Sicuro di avere l''Orda ai suoi ordini, Sargeras ordinò di scatenare l''invasione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1963, 'itIT', 'Unendo i loro sforzi, Medivh e gli Stregoni del Concilio dell''Ombra aprirono il varco dimensionale conosciuto come Portale Oscuro. Questo portale collegava Azeroth a Draenor ed era sufficientemente grande da permettere il passaggio di un esercito. Gul''dan inviò degli esploratori Orchi per raccogliere informazioni sulla terra che voleva conquistare: al loro ritorno, il Concilio dell''Ombra si convinse definitivamente che Azeroth era una facile preda.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1964, 'itIT', 'Sempre più convinto che Gul''dan stesse conducendo il proprio popolo alla rovina, Durotan alzò di nuovo la voce contro gli Stregoni. Il coraggioso guerriero affermò che essi stavano distruggendo la purezza dello spirito degli Orchi e che quell''insensata invasione sarebbe stata la loro fine. Gul''dan, che non poteva eliminare una figura così popolare, vide come unica soluzione l''esilio di Durotan e del suo Clan Lupi Bianchi nelle estreme regioni del nuovo mondo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1965, 'itIT', 'Dopo che gli esiliati Lupi Bianchi ebbero attraversato il portale, altri clan degli Orchi li seguirono. Questi crearono rapidamente un accampamento nella Palude Nera, un''area oscura e paludosa a est del Regno di Roccavento. Quando gli Orchi iniziarono a spostarsi nei nuovi territori, si scontrarono immediatamente con i difensori Umani di Roccavento.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1966, 'itIT', 'Anche se quelle schermaglie furono di poco conto, permisero alle due fazioni di scoprire punti di forza e di debolezza della specie rivale. Llane e Lothar non riuscirono però a capire quanti fossero realmente gli Orchi e poterono solo fare una stima delle forze che avrebbero dovuto affrontare.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1967, 'itIT', 'Dopo alcuni anni, il grosso dell''Orda orchesca raggiunse Azeroth e Gul''dan ritenne che fosse il momento di sferrare il colpo decisivo contro gli Umani. L''Orda scagliò tutta la sua potenza sull''impreparato Regno di Roccavento.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1968, 'itIT', 'Mentre le forze di Azeroth e dell''Orda si scontravano in tutto il Regno di Roccavento, i conflitti interni cominciarono a pesare su entrambi gli eserciti. Re Llane, che riteneva impossibile che orride bestie come gli Orchi potessero conquistare Azeroth, rimase orgogliosamente nella capitale Roccavento. Ser Lothar invece riteneva che fosse necessario lanciarsi all''attacco dei nemici e fu così costretto a scegliere fra le sue convinzioni e la fedeltà al Re.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1969, 'itIT', 'Seguendo il suo istinto, Lothar assaltò Karazhan, la torre fortezza di Medivh, con l''aiuto di Khadgar, il giovane apprendista del Mago. Khadgar e Lothar insieme riuscirono a sconfiggere il Guardiano posseduto, che come sospettavano era stato la causa scatenante del conflitto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1970, 'itIT', 'Uccidendo il corpo di Medivh, Lothar e il giovane apprendista bandirono inconsciamente lo spirito di Sargeras nell''abisso. Come conseguenza, l''anima pura di Medivh si ritrovò finalmente libera... e prese a vagare per il piano astrale per molti anni a venire.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1971, 'itIT', 'Anche se Medivh era stato sconfitto, l''Orda continuò ad abbattersi sui difensori di Roccavento. Mentre la vittoria finale dell''Orda si avvicinava, Orgrim Martelfato, uno dei più grandi Capoclan degli Orchi, iniziò ad accorgersi della corruzione che si era diffusa fra i clan da quando avevano lasciato Draenor.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1972, 'itIT', 'Il suo vecchio compagno, Durotan, fece ritorno dall''esilio e lo mise nuovamente in guardia dal tradimento di Gul''dan. Accortosi dell''accaduto, Gul''dan inviò degli assassini che uccisero Durotan e la sua famiglia, salvo il figlio più piccolo. Senza che Martelfato lo sapesse, il piccolo di Durotan venne trovato da un ufficiale Umano, Aedelas Molonero, che ne fece il suo schiavo.$B$BQuel piccolo Orco sarebbe diventato un giorno il più grande condottiero che il suo popolo avrebbe mai avuto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1973, 'itIT', 'Infuriato per la morte di Durotan, Orgrim decise di liberare l''Orda dalla corruzione demoniaca e riuscì ad assumere il ruolo di Capoguerra dell''Orda, uccidendo il corrotto burattino di Gul''dan, Manonera. Sotto la sua guida decisa, l''inarrestabile Orda giunse infine ad assediare il Forte di Roccavento.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1974, 'itIT', 'Re Llane aveva grandemente sottovalutato la forza dell''Orda e si ritrovò così ad assistere impotente alla caduta del suo regno per mano degli invasori dalla pelle verde. Infine venne ucciso da uno degli assassini più abili del Concilio dell''Ombra: Garona, la Mezz''Orchessa.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1975, 'itIT', 'Lothar e i suoi guerrieri, di ritorno da Karazhan, speravano di porre fine al massacro e di salvare ciò che restava della loro terra natale. Si accorsero però di essere arrivati troppo tardi: del regno che conoscevano rimanevano solo delle rovine fumanti. L''Orda orchesca continuò a devastare le terre, conquistando tutte le regioni circostanti. Costretti a nascondersi, Lothar e i suoi compagni giurarono solennemente che sarebbero riusciti a riconquistare la loro patria a ogni costo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1976, 'itIT', 'Lothar radunò ciò che restava degli eserciti di Azeroth, sconfitti nella battaglia del Forte di Roccavento, e li guidò in un esodo via mare alla volta del regno settentrionale di Lordaeron. Convinti che l''Orda avrebbe finito per annientare l''intera umanità se nessuno l''avesse fermata, i capi delle sette nazioni degli Umani si incontrarono e decisero di unirsi in quella che sarebbe divenuta nota come l''Alleanza di Lordaeron.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1977, 'itIT', 'Per la prima volta in quasi tremila anni, le diverse nazioni di Arathor si riunirono sotto uno stendardo comune. Nominato Comandante Supremo delle Forze dell''Alleanza, Lothar preparò i suoi eserciti per fronteggiare l''arrivo dell''Orda.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1978, 'itIT', 'Con l''aiuto dei suoi Tenenti, Uther l''Araldo della Luce, l''Ammiraglio Daelin Marefiero e Turalyon, Lothar riuscì a convincere le razze semi-umane di Lordaeron a fare fronte comune contro la minaccia imminente. L''Alleanza riuscì a ottenere il sostegno dei taciturni Nani di Forgiardente e di un piccolo gruppo di Alti Elfi di Quel''Thalas.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1979, 'itIT', 'Gli Elfi, sotto la guida di Anasterian Solealto, si dimostrarono per lo più poco interessati al conflitto: essi erano però tenuti a prestare aiuto a Lothar in quanto discendente dalla casata Arathi che in passato aveva portato soccorso agli Elfi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1980, 'itIT', 'L''Orda, ora agli ordini del Capoguerra Martelfato, richiamò altri Orchi dalle terre di Draenor e incorporò fra le sue file anche i Troll delle Foreste Amani. Lanciatasi in un''enorme campagna per rovesciare il regno nanico di Khaz Modan e le regioni meridionali di Lordaeron, l''Orda riuscì a spazzare via facilmente qualsiasi resistenza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1981, 'itIT', 'Le epiche battaglie della Seconda Guerra variarono da grandi scontri navali a devastanti combattimenti aerei. L''Orda era riuscita a impadronirsi di un potente manufatto, noto come Anima del Demone, e lo aveva utilizzato per ridurre in schiavitù l''antica Regina dei Draghi, Alexstrasza. Minacciando di distruggere le sue preziose uova, l''Orda l''aveva costretta a inviare in battaglia i suoi figli più grandi. I nobili Draghi Rossi furono costretti a combattere per l''Orda... e lo fecero.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1982, 'itIT', 'La guerra devastò i continenti di Khaz Modan, Lordaeron e Azeroth stessa. Durante la campagna settentrionale, l''Orda arrivò a bruciare anche i confini di Quel''Thalas, spingendo così gli Elfi a unirsi a pieno titolo alla causa dell''Alleanza. Le più grandi città di Lordaeron vennero devastate e rase al suolo durante il conflitto. Eppure, nonostante l''assenza di rinforzi e la schiacciante disparità, Lothar e i suoi alleati riuscirono a tenere a freno l''avanzata del nemico.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1983, 'itIT', 'Durante gli ultimi giorni della Seconda Guerra, quando la vittoria dell''Orda sull''Alleanza sembrava ormai inevitabile, un grave conflitto scoppiò fra i due Orchi più potenti di Azeroth. Mentre Martelfato preparava l''assalto finale contro la capitale di Lordaeron per spazzare via quanto restava dell''Alleanza, Gul''dan e i suoi seguaci abbandonarono le loro posizioni, salpando per mare.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1984, 'itIT', 'Martelfato, infuriato e privato di quasi la metà delle sue forze a causa del tradimento di Gul''dan, fu costretto a ritirarsi e a rinunciare alla migliore occasione per annientare l''Alleanza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1985, 'itIT', 'Gul''dan, accecato dalla brama di potere e desideroso di diventare un dio, si mise alla ricerca della sommersa Tomba di Sargeras, dove credeva fosse celato il potere supremo. Dato che aveva già condannato gli Orchi suoi compagni a divenire schiavi della Legione Infuocata, Gul''dan non ebbe alcuna remora nel venir meno ai suoi impegni con Martelfato.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1986, 'itIT', 'Supportato dai Clan Razziatempesta e Martello del Crepuscolo, Gul''dan riuscì a riportare in superficie la Tomba di Sargeras. Quando aprì l''antica cripta, al suo interno trovò però ad attenderlo solo dei folli demoni.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1987, 'itIT', 'Intenzionato a punire gli Orchi fuggiaschi per il loro tradimento, Martelfato inviò le sue forze a uccidere Gul''dan e a riportare indietro i rinnegati superstiti. Nel frattempo Gul''dan pagò la sua follia: venne fatto a pezzi dai folli demoni che aveva liberato. Perso il loro condottiero, i clan ribelli caddero rapidamente davanti alla collera delle schiere di Martelfato.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1988, 'itIT', 'Anche se la ribellione era stata domata, l''Orda non riuscì a riprendersi dalle gravi perdite che aveva subito. Il tradimento di Gul''dan aveva dato all''Alleanza una nuova speranza, permettendole di radunarsi e di lanciarsi al contrattacco.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1989, 'itIT', 'Lothar, vedendo che l''Orda si stava sgretolando dall''interno, radunò tutte le forze a sua disposizione e spinse Martelfato a sud, nel cuore delle devastate terre di Roccavento. Lì le forze dell''Alleanza intrappolarono l''Orda in ritirata all''interno della fortezza vulcanica dei Bastioni di Roccianera. Lothar cadde in battaglia ai piedi dei Bastioni ma il suo Tenente, Turalyon, si mise alla guida delle forze dell''Alleanza nel momento decisivo e ricacciò l''Orda nella terribile Palude del Dolore.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1990, 'itIT', 'Le truppe di Turalyon riuscirono quindi a distruggere il Portale Oscuro, il mistico varco che collegava gli Orchi alle loro terre natali di Draenor. Senza rinforzi e divisa dalle lotte intestine, l''Orda finì per crollare dinanzi alla forza dell''Alleanza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (1991, 'itIT', 'I clan degli Orchi, messi in fuga, vennero rapidamente catturati e rinchiusi in campi di prigionia. L''Orda sembrava definitivamente sconfitta, eppure molti si mostrarono scettici sul perdurare della pace. Khadgar, ora Arcimago di una certa fama, convinse l''alto comando dell''Alleanza a costruire la fortezza di Guardiafatua per tenere sotto controllo le rovine del Portale Oscuro e scongiurare nuove invasioni da Draenor.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2012, 'itIT', 'Kil''jaeden rispedì la bara di ghiaccio di Ner''zhul nel mondo di Azeroth. Il durissimo cristallo sfrecciò nel cielo notturno e finì per toccare terra nel continente artico di Nordania, arrestandosi in profondità sotto il Ghiacciaio delle Ossa. Il cristallo gelato, danneggiato durante la violenta discesa, assunse la forma di un trono, sul quale ben presto prese ad agitarsi il vendicativo spirito di Ner''zhul.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2013, 'itIT', 'Dall''interno del suo Trono di Ghiaccio, Ner''zhul iniziò a espandere la sua coscienza, arrivando a contaminare le menti dei nativi di Nordania. Senza eccessivo sforzo ridusse in schiavitù numerose creature, fra le quali i Troll dei Ghiacci e i feroci wendigo, attirando i loro fratelli malvagi nella sua ombra sempre più fitta. I suoi poteri psichici si rivelarono virtualmente illimitati e gli consentirono di creare un piccolo esercito che trovò riparo nei gelidi labirinti della Corona di Ghiaccio.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2014, 'itIT', 'Mentre il Re dei Lich imparava a controllare le sue capacità in continua crescita sotto la costante guardia dei Signori del Terrore, scoprì un remoto insediamento umano situato ai margini della grande Dracombra. D''impulso, Ner''zhul decise allora di mettere alla prova le sue capacità sugli ignari Umani.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2015, 'itIT', 'Ner''zhul scagliò sulle distese artiche una Piaga di non morti fuoriuscita dalle profondità del Trono di Ghiaccio. Controllandola con la sua forza di volontà, la condusse direttamente sul villaggio degli Umani. Nel giro di tre giorni tutti gli abitanti erano morti e, poco dopo, si risvegliarono come zombi. Ner''zhul riusciva ad avvertire i loro spiriti e i loro pensieri come fossero suoi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2016, 'itIT', 'Quella cacofonia di voci nella sua mente rese Ner''zhul ancora più potente, quasi potesse attingere il nutrimento di cui aveva bisogno dagli spiriti. Si accorse che era facile controllare le azioni dei non morti, spingendoli a fare qualunque cosa egli volesse.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2017, 'itIT', 'Nei mesi seguenti, Ner''zhul continuò a sperimentare la Piaga dei non morti soggiogando ogni abitante umano di Nordania. Il suo esercito di non morti cresceva di giorno in giorno e il momento della prova più importante si avvicinava.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2018, 'itIT', 'Nel frattempo, nelle terre del sud provate dalla guerra, ciò che restava dell''Orda lottava per sopravvivere. Mentre Grommash Malogrido e il suo Clan Cantaguerra riuscirono a sfuggire alla cattura, Occhiotetro e il Clan Guerci Insanguinati furono rinchiusi nei campi di prigionia di Lordaeron. Nonostante avessero cercato più volte di fuggire, i custodi avevano sempre represso con brutalità ogni loro tentativo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2019, 'itIT', 'Nel frattempo, all''insaputa dell''Alleanza, un folto gruppo di Orchi vagava ancora per le distese settentrionali di Khaz Modan. Il Clan Fauci di Drago, guidato dal pericoloso Stregone Nekros, utilizzava un antico manufatto noto come Anima del Demone per controllare la Regina dei Draghi Alexstrasza e il suo stormo. Con la Regina dei Draghi tenuta in ostaggio, Nekros radunò in segreto un esercito all''interno della roccaforte abbandonata, e secondo alcuni maledetta, dei Granmartello: Grim Batol.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2020, 'itIT', 'Intenzionato a scagliare le proprie forze e i potenti Draghi Rossi contro l''Alleanza, Nekros sperava di riunire l''Orda e di lanciarla di nuovo alla conquista di Azeroth. La sua visione non riuscì però a concretizzarsi: un piccolo gruppo di combattenti, guidati dal Mago umano Rhonin, riuscì a distruggere l''Anima del Demone e a liberare la Regina dei Draghi dal controllo di Nekros.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2021, 'itIT', 'Infuriati, i draghi di Alexstrasza distrussero Grim Batol, riducendo in cenere buona parte del Clan Fauci di Drago. I sogni di riunificazione di Nekros si infransero definitivamente quando le truppe dell''Alleanza circondarono gli Orchi superstiti per poi condurli nei campi di prigionia. La sconfitta del Clan Fauci di Drago mise fine alla sete di sangue degli Orchi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2022, 'itIT', 'Passarono i mesi e nuovi Orchi vennero catturati e imprigionati. I campi cominciarono a diventare sovraffollati e l''Alleanza fu costretta a edificarne di nuovi nelle pianure a sud delle Montagne d''Alterac. Per mantenere e rifornire i nuovi campi, Re Terenas fu costretto a imporre una nuova tassa sulle nazioni facenti parte dell''Alleanza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2023, 'itIT', 'Questa tassa, insieme alle tensioni politiche legate a delle dispute sui confini, finì per creare un malcontento diffuso. Sembrava che il fragile patto che aveva unito le nazioni degli Umani nella loro ora più cupa fosse ormai sul punto di rompersi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2024, 'itIT', 'In quella situazione di instabilità, molti dei custodi dei campi di prigionia si accorsero di uno strano mutamento negli Orchi reclusi. I loro tentativi di fuga, come pure le risse fra prigionieri, erano calati drasticamente con il passare del tempo. Gli Orchi stavano diventando letargici, come se stessero spegnendosi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2025, 'itIT', 'Anche se non era facile crederlo, gli Orchi, un tempo considerati la razza più aggressiva mai comparsa su Azeroth, avevano perso del tutto la loro volontà di combattere. Quello strano letargo lasciò perplessi i condottieri dell''Alleanza e continuò a diffondersi fra gli Orchi, indebolendoli.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2026, 'itIT', 'Alcuni azzardarono l''ipotesi di una strana malattia degli Orchi come causa della perdita di vitalità. Ma l''Arcimago Antonidas di Dalaran aveva un''altra teoria: dopo aver studiato tutto ciò che si conosceva sulla storia degli Orchi, egli scoprì che essi erano rimasti per generazioni sotto la devastante influenza del potere dei demoni.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2027, 'itIT', 'Secondo lui, gli Orchi erano stati corrotti da quei poteri addirittura antecedentemente la prima invasione di Azeroth. I demoni avevano modificato il sangue degli Orchi, donando loro una forza, una resistenza e un''aggressività innaturali.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2028, 'itIT', 'Antonidas affermò che il letargo comune a tutti gli Orchi non era una malattia, ma una conseguenza del venire meno degli effetti delle magie degli Stregoni che li avevano resi temibili guerrieri assetati di sangue.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2029, 'itIT', 'I sintomi erano molto chiari, ma Antonidas non riuscì a trovare una cura in grado di rimediare alla condizione degli Orchi. Anche perché molti dei suoi colleghi Maghi e diversi condottieri dell''Alleanza obiettarono, affermando che guarire gli Orchi fosse un''inutile imprudenza. Riflettendo sulle misteriose condizioni degli Orchi, Antonidas giunse alla conclusione che il rimedio, quale che fosse, dovesse essere di natura spirituale.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2030, 'itIT', 'Il capo guardiano dei campi di prigionia, Aedelas Molonero, osservava gli Orchi dalla sua roccaforte-prigione, Durnholde. Un Orco in particolare aveva attirato il suo interesse: il piccolo orfano che aveva trovato quasi diciotto anni prima. Molonero lo aveva cresciuto come il suo schiavo preferito e gli aveva dato il nome di Thrall. Gli aveva insegnato nozioni di tattica, filosofia e combattimento. Thrall era stato persino addestrato come gladiatore, perché il malvagio guardiano mirava a farne un''arma al suo servizio.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2031, 'itIT', 'Nonostante la rigida educazione, il giovane Thrall divenne un Orco robusto e astuto. Quando raggiunse la maturità venne a conoscenza di ciò che era accaduto agli altri Orchi, che non aveva mai incontrato: dopo la loro sconfitta erano quasi tutti rinchiusi nelle prigioni. Si diceva però che Martelfato, il loro condottiero, fosse fuggito da Lordaeron e vivesse in clandestinità. Solo il suo clan di disperati osava operare in segreto, cercando di sottrarsi al vigile occhio dell''Alleanza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2032, 'itIT', 'Inesperto ma ricco di risorse, Thrall decise di fuggire dalla fortezza di Molonero e di mettersi in cerca dei suoi simili. Durante i suoi viaggi visitò i campi di prigionia e scoprì che la sua razza, un tempo potente e fiera, era ora stranamente letargica e spaventata. Senza aver trovato i prodi guerrieri che sperava, Thrall si allontanò alla ricerca dell''ultimo Capoclan imbattuto, Grommash Malogrido.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2033, 'itIT', 'Costantemente braccato dagli Umani, Malogrido manteneva comunque l''incrollabile volontà di combattere tipica dell''Orda. Aiutato solo dai membri del suo clan, quello dei Cantaguerra, Malogrido portava avanti una guerra clandestina contro l''oppressione della sua gente. Purtroppo non era mai riuscito a trovare il modo di risvegliare dal torpore gli Orchi catturati. Il giovane Thrall, colpito dagli ideali che animavano Malogrido, sviluppò un profondo rispetto per l''Orda e le sue tradizioni guerriere.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2034, 'itIT', 'Cercando di scoprire la verità sulle sue origini, Thrall viaggiò verso nord per trovare il leggendario Clan Lupi Bianchi. Apprese così che Gul''dan li aveva esiliati durante le fasi iniziali della Prima Guerra. Scoprì inoltre di essere figlio ed erede dell''eroe orchesco Durotan, il vero Capoclan dei Lupi Bianchi, assassinato quasi vent''anni prima.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2035, 'itIT', 'Sotto la tutela del venerabile Sciamano Drek''thar, Thrall studiò l''antica cultura sciamanica del proprio popolo, che era stata dimenticata durante il malvagio governo di Gul''dan. Con il passare del tempo, Thrall divenne un potente Sciamano e prese il suo posto come legittimo Capoclan degli esiliati Lupi Bianchi. Dotato del potere degli elementi stessi e determinato a seguire il proprio destino, Thrall partì, deciso a liberare i clan prigionieri e a curare la propria razza dalla corruzione demoniaca.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2036, 'itIT', 'Durante i suoi viaggi, Thrall si imbatté nel vecchio Capoguerra Orgrim Martelfato, ridotto a vivere come eremita da ormai molti anni. Martelfato, che era stato un buon amico del padre di Thrall, decise di seguire il giovane e visionario Orco per aiutarlo a liberare i clan. Sostenuto da molti Capoclan veterani, Thrall riuscì infine a ridare vitalità all''Orda, donando alle proprie genti una nuova identità spirituale.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2037, 'itIT', 'Per simboleggiare la rinascita del proprio popolo, Thrall tornò alla fortezza di Molonero, Durnholde, per porre fine una volta per tutte alle attività del suo vecchio padrone assediando i campi di prigionia. La vittoria fu però ottenuta a caro prezzo: durante la liberazione di un campo, Martelfato cadde in battaglia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2038, 'itIT', 'Thrall raccolse il leggendario martello da guerra di Martelfato e indossò la sua armatura a piastre nere, diventando così il nuovo Capoguerra dell''Orda. Nel corso dei mesi seguenti, la piccola ma attiva Orda di Thrall devastò diversi campi di prigionia, avendo la meglio sull''Alleanza. Incoraggiato dal suo mentore e migliore amico, Grommash Malogrido, Thrall si impegnò a fondo per fare in modo che la sua gente non fosse mai più ridotta in schiavitù.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2039, 'itIT', 'Mentre Thrall liberava i suoi fratelli a Lordaeron, Ner''zhul continuava ad accrescere il proprio potere a Nordania. Sopra il Ghiacciaio delle Ossa venne realizzata una grande cittadella per ospitare le nuove legioni di non morti. Mentre il Re dei Lich estendeva la sua influenza sulla regione, un misterioso impero si oppose al suo potere.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2040, 'itIT', 'L''antico regno sotterraneo di Azjol-Nerub, fondato da una razza di sinistri ragni senzienti, inviò infatti le proprie truppe scelte all''assalto della Corona di Ghiaccio per porre fine ai folli sogni di dominio del Re dei Lich. Con sua grande frustrazione, Ner''zhul scoprì che i malvagi Nerubiani erano immuni non sono alla Piaga, ma anche alle sue capacità di controllo telepatico.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2041, 'itIT', 'I Signori dei Ragni Nerubiani avevano ai loro ordini nutrite forze militari e potevano contare su una rete di gallerie che copriva quasi metà della regione di Nordania. Le loro azioni mordi e fuggi contro le roccaforti del Re dei Lich si rivelarono sempre efficaci. Alla fine, però, Ner''zhul vinse la guerra contro i Nerubiani: grazie all''aiuto dei temibili Signori del Terrore e ai numerosi non morti, il Re dei Lich invase Azjol-Nerub e fece crollare i suoi templi sotterranei sopra i suoi abitanti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2042, 'itIT', 'Anche se i Nerubiani erano immuni alla sua Piaga, Ner''zhul sfruttò i suoi crescenti poteri da negromante per rianimare i cadaveri dei Guerrieri Ragno caduti, piegandoli alla sua volontà. In omaggio al valore degli avversari, Ner''zhul decise di adottare lo stile architettonico tipico dei Nerubiani per creare le proprie fortezze e strutture.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2043, 'itIT', 'Dominatore incontrastato del proprio regno, il Re dei Lich iniziò i preparativi per la sua vera missione. Raggiungendo le terre degli Umani grazie ai propri poteri psichici, egli richiamò a sé ogni anima oscura disposta ad ascoltare le sue parole...') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2044, 'itIT', 'Alcuni individui dal grande potere, sparsi per il mondo, udirono il richiamo mentale del Re dei Lich proveniente da Nordania. Il più importante fra loro era l''Arcimago di Dalaran, Kel''Thuzad, uno dei membri anziani del Kirin Tor, il consiglio che governava su Dalaran. Da anni veniva visto con sospetto a causa dell''insistenza con cui voleva studiare le arti proibite della negromanzia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2045, 'itIT', 'Intenzionato ad apprendere il più possibile sul mondo della magia e sulle sue oscure meraviglie, egli era frustrato dinanzi ai limiti posti dai suoi pari, che riteneva troppo legati al passato. Dopo aver udito il potente richiamo giunto da Nordania, l''Arcimago si dedicò anima e corpo alla creazione di un legame con la misteriosa voce. Convinto che il Kirin Tor fosse troppo debole per comprendere le arti oscure, egli si dimise dall''incarico, deciso ad apprendere il più possibile dal potentissimo Re dei Lich.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2046, 'itIT', 'Rinunciando alle sue ricchezze e al prestigio della propria posizione, Kel''Thuzad si allontanò dal Kirin Tor, lasciando Dalaran per sempre. Guidato dalla voce del Re dei Lich, che echeggiava di continuo nella sua mente, vendette i suoi possedimenti e mise il ricavato al sicuro. Viaggiando da solo, dopo aver percorso un''enorme distanza, giunse infine sulle gelide coste di Nordania.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2047, 'itIT', 'Intenzionato a raggiungere la Corona di Ghiaccio per offrire i propri servigi al Re dei Lich, l''Arcimago attraversò le rovine di Azjol-Nerub, devastate dalla guerra. Kel''Thuzad vide così personalmente di cosa erano capaci i feroci poteri di Ner''zhul e si convinse che allearsi con il misterioso Re dei Lich sarebbe stata una mossa saggia, nonché potenzialmente vantaggiosa.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2048, 'itIT', 'Dopo lunghi mesi di viaggio nelle desolate lande artiche, Kel''Thuzad arrivò finalmente al Ghiacciaio delle Ossa. Si avvicinò senza paura all''oscura cittadella di Ner''zhul e rimase colpito quando le sue sentinelle non morte lo lasciarono passare, come se fosse atteso.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2049, 'itIT', 'Kel''Thuzad discese nelle profondità della terra ghiacciata fino a raggiungere la base del Ghiacciaio. Là, in un''infinita caverna di ghiaccio e ombra, si prostrò dinanzi al Trono di Ghiaccio, offrendo la propria anima all''oscuro signore della morte.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2050, 'itIT', 'Il Re dei Lich era soddisfatto del suo nuovo seguace: promise a Kel''Thuzad immortalità e grandi poteri in cambio di fedeltà e obbedienza. Ansioso di scoprire nuove conoscenze oscure, Kel''Thuzad accettò di compiere la missione a lui affidata: tornare nel mondo degli Umani e creare una nuova religione che adorasse il Re dei Lich come un dio.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2051, 'itIT', 'Per aiutare l''Arcimago a raggiungere lo scopo, Ner''zhul non intaccò l''umanità di Kel''Thuzad. Il Mago, vecchio ma ancora estremamente carismatico, fu incaricato di utilizzare i suoi poteri di illusione e persuasione per convincere le masse di Lordaeron a credere alle sue parole. Una volta ottenuto questo risultato, avrebbe offerto loro una visione della possibile nuova società e una nuova figura da onorare come Re.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2052, 'itIT', 'Kel''Thuzad tornò così a Lordaeron in incognito e, nel volgere di tre anni, utilizzò le sue fortune e il suo intelletto per organizzare una fratellanza segreta di uomini e donne che condividevano la sua visione. Quella fratellanza, che egli chiamò Culto dei Dannati, prometteva agli accoliti eguaglianza sociale e vita eterna su Azeroth in cambio dei loro servigi e dell''obbedienza a Ner''zhul.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2053, 'itIT', 'Con il passare dei mesi, Kel''Thuzad trovò molte persone disposte a unirsi al culto, soprattutto fra i lavoratori oppressi di Lordaeron. Fu sorprendentemente facile riuscire a raggiungere l''obiettivo prefissato, cioè quello di trasferire la fede dei cittadini nella Luce Sacra nell''adorazione per l''oscura ombra di Ner''zhul. Il Culto dei Dannati divenne sempre più potente e influente, mentre Kel''Thuzad teneva le autorità di Lordaeron all''oscuro del suo operato.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2054, 'itIT', 'Dopo la vittoria di Kel''Thuzad a Lordaeron, il Re dei Lich mise a punto gli ultimi preparativi per attaccare gli Umani. Una volta convogliate le energie della Piaga su diversi manufatti chiamati Calderoni della Piaga, Ner''zhul ordinò a Kel''Thuzad di trasportarli a Lordaeron per nasconderli all''interno dei vari villaggi controllati dal culto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2055, 'itIT', 'I calderoni, difesi dai cultisti più fedeli, avrebbero agito da generatori della Piaga, trasmettendola a tutte le ignare fattorie e centri abitati della terra settentrionale di Lordaeron.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2056, 'itIT', 'Il piano del Re dei Lich funzionò alla perfezione. Molti villaggi di Lordaeron furono contaminati quasi immediatamente. Proprio come a Nordania, i cittadini che avevano contratto la Piaga morirono e risorsero come schiavi agli ordini del Re dei Lich.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2057, 'itIT', 'Essi gioivano all''idea dell''immortalità di cui avrebbero goduto come non morti. Mentre la Piaga si diffondeva, sempre più zombi nacquero nelle terre del nord. Kel''Thuzad osservò il crescente esercito del Re dei Lich e gli diede il nome di Flagello, perché presto esso avrebbe marciato fino ai cancelli di Lordaeron e spazzato via la razza umana dalla faccia del mondo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2064, 'itIT', 'Dopo lunghi mesi di preparativi, Kel''Thuzad e il suo Culto dei Dannati lanciarono finalmente il loro primo assalto, scatenando la Piaga dei non morti su Lordaeron. Uther e i suoi Paladini si recarono a indagare nelle regioni infette nella speranza di riuscire a fermare la Piaga. Nonostante i loro sforzi, questa continuò a diffondersi, minacciando di mandare in frantumi l''Alleanza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2065, 'itIT', 'Mentre le file dei non morti devastavano Lordaeron, il Principe Arthas, unico figlio di Terenas, si fece avanti per affrontare il Flagello. Arthas riuscì a uccidere Kel''Thuzad, ma non a evitare che le forze dei non morti crescessero con ogni soldato ucciso mentre compiva il suo dovere. Frustrato dinanzi a un nemico apparentemente inarrestabile, Arthas tentò azioni sempre più drastiche, fino a quando i suoi stessi compagni lo avvisarono che stava pian piano perdendo la sua umanità.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2066, 'itIT', 'Alla fine furono proprio le paure e le decisioni di Arthas a condurlo alla rovina. Egli risalì alla fonte della Piaga, a Nordania, intenzionato a cancellarla una volta per sempre. Fu invece proprio il Principe Arthas a cadere preda del tremendo potere del Re dei Lich. Credendo di essere a un passo dal salvare il suo popolo, Arthas impugnò Gelidanima, una lama runica maledetta.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2067, 'itIT', 'La spada gli garantì un terribile potere ma finì per rubargli l''anima, tramutandolo nel più potente fra i Cavalieri della Morte del Re dei Lich. Senza più il proprio spirito e dopo essere precipitato nella follia, Arthas guidò il Flagello contro il suo stesso regno e arrivò a uccidere suo padre, Re Terenas, ponendo così Lordaeron sotto il giogo del Re dei Lich.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2068, 'itIT', 'Nonostante avesse oramai sconfitto tutte le persone che considerava nemiche, Arthas era ancora tormentato dal fantasma di Kel''Thuzad. Lo spirito disse ad Arthas di dover essere riportato in vita per attuare la prossima fase del piano del Re dei Lich. Per farlo, Arthas avrebbe dovuto portare le spoglie mortali di Kel''Thuzad al mistico Pozzo Solare, situato all''interno del regno eterno degli Alti Elfi, Quel''Thalas.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2069, 'itIT', 'Arthas e il suo Flagello invasero Quel''Thalas e strinsero d''assedio le deboli difese degli Elfi. Sylvanas Ventolesto, il Generale dei Guardaboschi di Lunargenta, si batté con valore, ma infine Arthas riuscì ad annientare l''esercito degli Alti Elfi e a raggiungere il Pozzo Solare. Per affermare appieno il suo dominio, egli rianimò il cadavere di Sylvanas come Banshee, condannandola a servire in eterno il conquistatore di Quel''Thalas come Non Morta.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2070, 'itIT', 'Arthas immerse infine i resti di Kel''Thuzad all''interno delle acque sacre del Pozzo Solare. Anche se le potenti acque dell''Eternità rimasero contaminate dal suo gesto, Kel''Thuzad tornò in vita come un Occultista Lich. Divenuto ora una creatura molto più potente, Kel''Thuzad espose il prossimo passo del progetto del Re dei Lich.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2071, 'itIT', 'Quando Arthas e il suo esercito di non morti si diressero verso sud, a Quel''Thalas non era rimasto in vita neppure un Elfo. La gloriosa dimora degli Alti Elfi, dopo aver resistito per oltre mille anni, era caduta.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2072, 'itIT', 'Quando Kel''Thuzad rinacque, Arthas condusse il Flagello verso sud, a Dalaran. Là il Lich intendeva impadronirsi del potente grimorio di Medivh, usarlo per evocare Archimonde e dare così il via all''ultima fase dell''invasione della Legione. Neppure i Maghi del Kirin Tor riuscirono a impedire alle forze di Arthas di rubare il grimorio di Medivh e presto Kel''Thuzad ebbe tutto il necessario per procedere con l''incantesimo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2073, 'itIT', 'Dopo diecimila anni, il potente Demone Archimonde e le sue schiere tornarono nel mondo di Azeroth. La loro destinazione finale non era però Dalaran: su ordine di Kil''jaeden stesso, Archimonde e i suoi demoni seguirono il Flagello dei non morti a Kalimdor, intenzionati a distruggere Nordrassil, l''Albero del Mondo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2074, 'itIT', 'Nel mezzo di quel caos, un misterioso e solitario profeta apparve per assistere le razze mortali. Questo profeta non era altri che Medivh, l''Ultimo Guardiano, miracolosamente tornato dalla Grande Oscurità per redimere i propri peccati. Medivh avvertì l''Orda e l''Alleanza del pericolo che incombeva su di loro e le esortò a unirsi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2075, 'itIT', 'Orchi e Umani, abituati a odiarsi da generazioni, non ne vollero sapere. Medivh fu pertanto costretto a trattare separatamente con le due razze, utilizzando le sue profezie e l''astuzia per guidarli attraverso il mare, fino alla leggendaria terra di Kalimdor. Lì, Orchi e Umani vennero presto in contatto con l''antica e dimenticata civiltà dei Kaldorei.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2076, 'itIT', 'Gli Orchi, guidati da Thrall, subirono una serie di sconfitte durante il viaggio attraverso le savane di Kalimdor. Anche se strinsero amicizia con Cairne Zoccolo Sanguinario e i suoi potenti guerrieri Tauren, molti Orchi caddero vittima della furia demoniaca che li aveva a lungo contaminati. Il più valoroso sottoposto di Thrall, Grommash Malogrido, arrivò a tradire l''Orda, abbandonandosi ai propri istinti.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2077, 'itIT', 'Mentre Malogrido e i suoi fidati Guerrieri Cantaguerra imperversavano per le foreste di Valtetra, si scontrarono con le Sentinelle degli Elfi della Notte. Certo che gli Orchi fossero tornati sul sentiero di guerra, il semidio Cenarius si fece avanti per respingere Malogrido e i suoi Orchi. Eppure furono costoro, spinti da una furia e un odio sovrannaturali, a uccidere Cenarius, corrompendo così l''antica foresta.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2078, 'itIT', 'Infine, però, Malogrido seppe riscattare il proprio onore, aiutando Thrall a sconfiggere Mannoroth, il signore dei demoni che aveva originariamente maledetto gli Orchi con il suo sangue ricolmo di furia e odio. Con la morte di Mannoroth, finalmente ebbe fine la maledizione degli Orchi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2079, 'itIT', 'Mentre Medivh si operava per convincere Orchi e Umani della necessità di un''alleanza, gli Elfi della Notte combatterono contro la Legione utilizzando le loro misteriose tattiche. Tyrande Soffiabrezza, l''immortale Gran Sacerdotessa delle Sentinelle degli Elfi della Notte, si batté disperatamente per impedire a demoni e non morti di conquistare le foreste di Valtetra. Tyrande si rese conto di aver bisogno di aiuto, così decise di risvegliare i Druidi Elfi della Notte dal loro sonno millenario.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2080, 'itIT', 'Facendo appello al suo antico amore, Malfurion Grantempesta, Tyrande riuscì a riorganizzare le sue truppe e a respingere la Legione. Con l''aiuto di Malfurion, la natura stessa si sollevò per annientare la Legione e il Flagello suo alleato.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2081, 'itIT', 'Mentre era in cerca di altri Druidi ibernati, Malfurion si imbatté nell''antica prigione desolata in cui aveva incatenato suo fratello Illidan. Convinta che quest''ultimo li avrebbe aiutati contro la Legione, Tyrande lo liberò: in effetti Illidan li aiutò per un certo periodo di tempo, prima di allontanarsi per perseguire i propri interessi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2082, 'itIT', 'Gli Elfi della Notte si prepararono allo scontro e affrontarono la Legione Infuocata con grande determinazione. Quest''ultima non aveva mai smesso di bramare il Pozzo dell''Eternità, da tempo sorgente dell''energia dell''Albero del Mondo e cuore del regno degli Elfi della Notte. Se il loro assalto all''Albero avesse avuto successo, i demoni avrebbero fatto letteralmente a pezzi tutto il mondo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2083, 'itIT', 'Quando la Legione invase Valtetra, Illidan venne liberato dalla sua prigione dopo diecimila anni di isolamento. Anche se inizialmente cercò di assecondare i propri compagni, la sua vera natura riprese presto il sopravvento e Illidan assorbì le energie di un potente manufatto, conosciuto come il Teschio di Gul''dan.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2084, 'itIT', 'Così facendo, sviluppò dei tratti demoniaci e vide crescere notevolmente il proprio potere. Si impadronì anche di alcuni dei ricordi di Gul''dan, in particolare quelli relativi alla Tomba di Sargeras, il luogo dove, secondo la leggenda, riposavano i resti del Titano Oscuro.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2085, 'itIT', 'Traboccante di potere e nuovamente libero di vagare per il mondo, Illidan partì deciso a conquistarsi una posizione di rilievo negli eventi in corso. Presto però dovette confrontarsi con Kil''jaeden, che gli fece un''allettante offerta. Kil''jaeden era adirato a causa della sconfitta di Archimonde sul Monte Hyjal, ma al momento aveva preoccupazioni più pressanti della vendetta.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2086, 'itIT', 'Rendendosi conto che la sua creatura, il Re dei Lich, era sempre più difficile da controllare a causa del suo potere, Kil''jaeden ordinò a Illidan di distruggere Ner''zhul e di porre per sempre fine al Flagello dei non morti. In cambio, Illidan avrebbe ricevuto poteri inimmaginabili e un posto d''onore fra i signori della Legione Infuocata.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2087, 'itIT', 'Illidan accettò e si mise immediatamente in marcia per distruggere il Trono di Ghiaccio, la gelida bara nella quale era contenuto lo spirito del Re dei Lich. Illidan sapeva che avrebbe avuto bisogno di un potente manufatto per distruggere il Trono di Ghiaccio: grazie alle nozioni apprese dai ricordi di Gul''dan, decise quindi di mettersi in cerca della Tomba di Sargeras per impossessarsi delle spoglie del Titano Oscuro.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2088, 'itIT', 'Egli chiese aiuto ad alcuni Alti Nobili, in debito con lui, e richiamò i Naga dalle loro oscure tane sommerse. Guidati dall''astuta Dama Vashj, i Naga aiutarono Illidan a raggiungere le Isole Disperse, dove sembrava si trovasse la Tomba di Sargeras.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2089, 'itIT', 'Appena Illidan partì insieme ai Naga, la Custode Maiev Cantombroso si mise sulle sue tracce. Maiev era stata per diecimila anni la carceriera di Illidan e non vedeva l''ora di rinchiuderlo nuovamente. Illidan seppe però dimostrarsi più astuto di lei e delle sue Custodi e, nonostante i loro sforzi, riuscì a impossessarsi dell''Occhio di Sargeras. Con il potente manufatto nelle sue mani, Illidan si diresse verso l''antica città dei Maghi di Dalaran.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2090, 'itIT', 'Grazie al potere aggiuntivo garantito dalle linee di faglia che percorrevano la città, Illidan utilizzò l''Occhio di Sargeras per lanciare un terrificante incantesimo contro la cittadella del Re dei Lich, la Corona di Ghiaccio, nella lontana Nordania. Il suo attacco superò le difese del Re dei Lich e arrivò persino a infrangere la volta celeste. All''ultimo però, l''incantesimo di Illidan fu fermato da suo fratello Malfurion e dalla Sacerdotessa Tyrande, giunti in aiuto di Maiev.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2091, 'itIT', 'Sapendo che Kil''jaeden non sarebbe stato soddisfatto del suo fallimento nel distruggere il Trono di Ghiaccio, Illidan fuggì nella dimensione desolata nota come Terre Esterne, ciò che restava di Draenor, l''antica terra natale degli Orchi. Lì sperava di eludere l''ira di Kil''jaeden, mentre pianificava le sue prossime mosse.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2092, 'itIT', 'Dopo essere riusciti a fermare Illidan, Malfurion e Tyrande tornarono a casa nella Foresta di Valtetra, per vegliare sulla propria gente. Maiev però non si arrese e seguì Illidan nelle Terre Esterne, determinata più che mai a ottenere giustizia.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2093, 'itIT', 'In quel periodo, il Flagello dei non morti aveva ormai trasformato Lordaeron e Quel''Thalas nelle desolate Terre Infette. Erano attive solo alcune sacche di resistenza dell''Alleanza. Uno di questi gruppi, composto principalmente da Alti Elfi, era guidato dall''ultimo discendente della dinastia Solealto: il Principe Kael''thas.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2094, 'itIT', 'Kael, a sua volta Mago di grande valore, non riponeva più alcuna fiducia nell''efficacia dell''antica Alleanza. Gli Alti Elfi piansero la perdita della loro terra natale e decisero di mutare nome in Elfi del Sangue, in onore dei loro compagni caduti. Mentre lottavano per tenere a bada il Flagello, subirono gli effetti della separazione dal Pozzo Solare, che da sempre gli aveva dato forza.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2095, 'itIT', 'Deciso a trovare un rimedio contro la dipendenza dalla magia della propria gente, Kael tentò l''inimmaginabile: scese a patti con la discendenza dagli Alti Nobili e si unì a Illidan e ai Naga, nella speranza di trovare una nuova fonte di potere magico alla quale attingere. Gli altri comandanti dell''Alleanza bollarono allora gli Elfi del Sangue come traditori, voltando loro le spalle.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2096, 'itIT', 'Senza un posto dove andare, Kael e i suoi Elfi del Sangue seguirono Dama Vashj fino alle Terre Esterne per aiutarla nel confronto con la Custode Maiev, che era riuscita a ricatturare Illidan. Unendo le forze, Naga ed Elfi del Sangue riuscirono a sconfiggere Maiev, liberando nuovamente Illidan. Quest''ultimo, restando nelle Terre Esterne, raccolse le proprie forze e si preparò a scagliare un secondo assalto contro il Re dei Lich e la sua fortezza della Corona di Ghiaccio.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2097, 'itIT', 'Ner''zhul, il Re dei Lich, sapeva di avere poco tempo a disposizione. Imprigionato nel Trono di Ghiaccio, temeva che Kil''jaeden avrebbe inviato i suoi agenti a distruggerlo. I danni causati dall''incantesimo di Illidan avevano scheggiato il Trono di Ghiaccio, riducendo così gradualmente il suo potere. Nel disperato tentativo di salvarsi, egli chiamò a sé il suo più potente servitore mortale: il Principe Arthas, Cavaliere della Morte.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2098, 'itIT', 'Anche se i suoi poteri erano ridotti a causa della debolezza del Re dei Lich, Arthas aveva comunque combattuto in una guerra civile a Lordaeron. Metà delle forze dei non morti guidate dalla Banshee Sylvanas Ventolesto avevano cercato di assumere il controllo dell''impero dei non morti. Convocato dal Re dei Lich, Arthas era stato costretto a lasciare il Flagello al comando del proprio Luogotenente, Kel''Thuzad, mentre la guerra divampava nelle Terre Infette.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2099, 'itIT', 'Infine, Sylvanas e i suoi non morti ribelli (conosciuti come Reietti) presero il controllo della capitale in rovina di Lordaeron. Edificando la loro base fra le macerie della città, i Reietti giurarono di sconfiggere il Flagello e di scacciare Kel''Thuzad e i suoi seguaci da quelle terre.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2100, 'itIT', 'Indebolito ma comunque determinato a salvare il proprio signore, Arthas raggiunse Nordania solo per trovare ad attenderlo i Naga e gli Elfi del Sangue di Illidan. Appoggiato dai suoi alleati Nerubiani, cercò di raggiungere prima delle forze di Illidan il Ghiacciaio delle Ossa per difendere il Trono di Ghiaccio.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2101, 'itIT', 'Benché indebolito, Arthas riuscì infine ad avere la meglio su Illidan, giungendo per primo al Trono di Ghiaccio. Impugnando la sua lama runica, Gelidanima, Arthas frantumò la gelida prigione del Re dei Lich, liberando così l''elmo e il pettorale corazzato incantati di Ner''zhul.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2102, 'itIT', 'Arthas indossò l''elmo dallo straordinario potere e divenne così il nuovo Re dei Lich. Gli spiriti di Ner''zhul e di Arthas si fusero in un solo potente essere, proprio come Ner''zhul aveva sempre sperato. Illidan e le sue truppe, sconfitti, furono costretti a tornare nelle Terre Esterne, mentre Arthas divenne una delle entità più potenti che il mondo avesse mai visto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2103, 'itIT', 'Attualmente Arthas, il nuovo e immortale Re dei Lich, risiede a Nordania, dove si dice che stia ricostruendo la cittadella della Corona di Ghiaccio. Il suo fidato Luogotenente, Kel''Thuzad, guida il Flagello nelle Terre Infette. A Sylvanas e ai suoi Reietti rimangono solo le Radure di Tirisfal, una piccola parte del regno devastato dalla guerra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2171, 'itIT', 'Fellari Frecciamorte$BCapitano dei Guardaboschi della Crociata Scarlatta$BCittadina di Quel''Thalas$BDispersa nella Selva Pinargento') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2211, 'itIT', 'Qui giace Grommash Malogrido, Capoclan dei Cantaguerra$B$BIn molti sensi, la maledizione della nostra gente è iniziata e si è conclusa con Grom. Il suo nome significa ''grande cuore'' nella nostra lingua antica. Senza ombra di dubbio ha mostrato di averlo davvero, affrontando da solo il demone Mannoroth e donandoci la libertà con il suo sangue.$B$BLok''tar ogar, fratello. Che i Cantaguerra non svaniscano mai.$B$BThrall, Capoguerra dell''Orda') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2251, 'itIT', 'Assalitori... da ogni lato.$B$BLo vedo nei loro occhi, i Mordilegno sono malvagi. Nemici.$B$BDevo proteggere la tribù. Devo proteggere Freddinverno. Devo scacciare gli invasori dalla nostra terra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2311, 'itIT', 'Questo scheletro intatto di Pteranodonte è stato recuperato dal remoto Cratere di Un''Goro. A giudicare dalla sua struttura, si tratta di una specie mai avvistata finora. Lo scheletro potrebbe essersi conservato per svariati secoli sotto il terreno fertile della regione.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2377, 'itIT', 'Annali del Borgo di Darrow
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2378, 'itIT', 'La Battaglia del Borgo di Darrow
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2379, 'itIT', 'I primi attacchi del Flagello sul Borgo di Darrow si limitarono a gruppetti di scheletri e non morti che vagavano ai margini del villaggio, e furono respinti. Ma il Flagello non si arrese di fronte alla tenacia dei difensori e la sua reazione non tardò ad arrivare. Alla prima ondata di attacchi ne seguì una seconda. Campioni Ghoul, servitori del Signore dei Ghoul Horgus, vennero giù urlando dalle colline e si scontrarono con i difensori assediati del Borgo di Darrow.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2380, 'itIT', 'I difensori erano deboli, ma in loro aiuto giunsero i Paladini della Mano d''Argento. Il loro capo, Davil Crokford, era nato al Borgo di Darrow. Egli condusse i propri seguaci al villaggio appena seppe dell''imminente attacco e insieme agli altri tenne a bada i servitori di Horgus. Quando lo stesso Horgus entrò in battaglia, egli si scontrò con Davil. Andarono avanti a combattere per diversi minuti. Alla fine Davil ebbe la meglio, ma fu ferito a morte e morì poco dopo aver sconfitto il Signore dei Ghoul.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2381, 'itIT', 'Lo scontro proseguì e il Capitano Tracciarossa guidò la propria milizia con coraggio. Avrebbe vinto, se non fosse stato corrotto dal Cavaliere della Morte Marduk Pozzanera. Durante la battaglia, Marduk si diresse verso Tracciarossa e ricorrendo alla magia nera gli strappò lo spirito dal corpo, trasformandolo in un''ombra malvagia del coraggioso capitano.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2382, 'itIT', 'A seguire, Tracciarossa diffuse la sua corruzione tra i difensori del Borgo di Darrow, i quali tradirono i propri alleati e li massacrarono. Quindi attaccarono il villaggio, casa per casa, uccidendo tutti coloro che si erano nascosti. Il resto dell''esercito del Flagello, insieme allo spirito corrotto del Capitano Tracciarossa, lasciò il Borgo di Darrow devastato e si diresse a Lordaeron, aggiungendo altro dolore e morti alla Seconda Guerra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2383, 'itIT', 'Il destino di Horgus il Devastatore
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2384, 'itIT', 'Il destino di Marduk Pozzanera
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2385, 'itIT', 'Il destino di Davil Fiocafiamma
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2386, 'itIT', 'Il destino di Joseph Tracciarossa
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2391, 'itIT', 'Il destino di Carlin Tracciarossa
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2413, 'itIT', 'Neve che acceca...$B$BDevo proteggere la tribù. Renderla forte. Devo essere forte.$B$BNon so...') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2414, 'itIT', 'Corroborante.$B$BPreparatene dell''altro.$B$BIl Corroborante rende i Freddinverno forti. Sconfigge i nostri nemici.$B$BI Freddinverno non hanno alleati. I Freddinverno sono forti. Hanno un grande potere.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2415, 'itIT', 'Ancora. Ne voglio ancora...$B$BI Freddinverno... non sono... deboli...') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2571, 'itIT', 'La Vigilia di Grande Inverno$B$BLe ultime stagioni di Azeroth vengono considerate come un periodo di cambiamento in molte culture. I Nani e i Tauren in particolare festeggiano l''arrivo del Grande Inverno, quando la terra viene ricoperta da un manto bianco e va incontro a un rinnovamento. Anche se le leggende condivise dalle varie razze di Azeroth non si discostano molto tra loro, ogni razza ha scelto un modo diverso per festeggiarle.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2572, 'itIT', 'La Leggenda di Babbo Inverno$B$BPare che il termine "Grande Inverno" si riferisca a una creatura soprannaturale che in molte culture prende il nome di Babbo Inverno. Secondo la leggenda, Babbo Inverno avrebbe ricoperto la terra con una coltre bianca durante il suo passaggio al termine delle stagioni. Nonostante la neve ricopra diverse zone di Azeroth, essa dà anche alla terra il tempo per rinascere e rinnovarsi.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2573, 'itIT', 'I Nani$B$BSempre alle prese con la ricerca delle loro origini, i Nani hanno scelto di festeggiare la stagione per onorare Babbo Inverno in persona. Essi lo considerano l''incarnazione di uno degli Dei Antichi di Azeroth, i Titani. Nonostante sostengano di discendere in un modo o nell''altro da queste creature mistiche, i Nani ritengono che la loro patria ricoperta di neve, Dun Morogh, sia il principale esempio delle benedizioni di Babbo Inverno.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2574, 'itIT', 'I Tauren$B$BI Tauren e la loro interpretazione sciamanica dell''inverno, oltre al loro recente interessamento nelle faccende dei Druidi, si sposano bene con la leggenda del Grande Inverno. Essi tuttavia si concentrano quasi esclusivamente sugli aspetti legati al rinnovamento, lasciando l''adorazione della leggenda a quelle razze, a loro dire, meno in armonia con la natura delle cose. Molti Tauren scelgono questo periodo come ringraziamento per le benedizioni della loro nuova casa a Mulgore.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2575, 'itIT', 'Banchetti$B$BL''idea di banchettare in questo periodo dell''anno affonda le sue radici nelle origini della leggenda stessa. Quando Babbo Inverno attraversò Azeroth, portando l''inverno al suo passaggio, si dice che avrebbe fornito una ricompensa a coloro che lo avessero accolto. Da qui l''idea di organizzare banchetti durante il Grande Inverno per riunire le comunità e condividere tutto ciò che avevano. Di solito era sufficiente una sola giornata di banchetti per festeggiare il cambiamento, in attesa del rinnovamento della terra.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2576, 'itIT', 'Usanze attuali$B$BAltre culture hanno cominciato a festeggiare la Vigilia di Grande Inverno, pur discostandosi dalla tradizione originale. Molte di queste usanze personalizzate sono solo un pretesto per fare baldoria e scambiarsi regali. A volte viene usata persino l''immagine di Babbo Inverno, ma più per scopi commerciali che come quella di un Titano soprannaturale.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2611, 'itIT', '...e lì troverete la spada leggendaria del Gran Signore Scarlatto, Brandicenere.$B$BNon è incredibile in cosa ci si possa imbattere durante una normale giornata di pesca?') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2787, 'itIT', 'Il suo nome ha portato la Luce nella buia Azeroth.$B$BIl suo valore ha abbattuto il muro della sofferenza.$B$BLa Mano d''Argento non avrebbe potuto fare di meglio che$B$Bconsegnare il mondo al cavaliere che si era offerto.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2788, 'itIT', 'Non gli interessava aumentare la propria fama,$B$Bné voleva comandare sulla sua razza.$B$BScelse di combattere per Lordaeron$B$Bnella speranza che i suoi compagni non dovessero farlo in futuro.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2789, 'itIT', 'La tragica storia di questo santissimo cavaliere$B$Bnon finirà con la sua morte.$B$BNoi continueremo a onorarlo e a ringraziarlo per ciò che ha fatto!$B$BUther vivrà per sempre nella gloria e nella Luce!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2790, 'itIT', 'Il suo nome non verrà dimenticato.$BIl suo sacrificio servirà$Bsempre a indicarci la via.$B$BLe catene che un tempo$Bsoffocavano il nostro respiro$Bora sono state spezzate.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2791, 'itIT', 'Senti il suo grido?$BUn grido di battaglia per l''Orda:$Bvittoria o morte!$B$BDobbiamo ricordarci della$Bsua forza di fronte alla morte.$BIl suo sogno ora è diventato realtà.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2792, 'itIT', 'Pericoli dappertutto!$BNemici che cercano di$Brimetterci in catene.$B$BQuando combattiamo, pensiamo a$Bcolui che ha fatto ciò che era necessario.$BLunga vita a Malogrido!') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2913, 'itIT', 'Anche se quasi sconfitto$BIl suo coraggio non vacillò$BEstrasse la spada e a capofitto$BLa folla malvagia caricò$B$BDa quel giorno tirannico$BNessuna spada o freccia$BNel corpo del signore nanico$BRiuscì mai a fare breccia') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2914, 'itIT', '...ma ella già lo sapeva. Si era rassegnata a vivere come una paria dopo aver barattato la propria anima in pezzi. Ne era valsa la pena per vendicarsi, o almeno così credeva.$B$BEbbe un''altra occasione per riconquistare la sua umanità. Tutto ciò che lo straniero le chiese in cambio fu la sua fiducia.$B$B"Accetto," disse Katreyn. "Non ho niente da perdere.".') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2918, 'itIT', 'Sono stato io. Non ricordo di averlo fatto, ma non può essere altrimenti.$B$BHo commesso dei peccati in passato. Una volta ho persino ucciso un uomo innocente. Ma stavolta è diverso.$B$BSono cambiato. Questi omicidi non sono stati una mia scelta. C''è una bestia che vive dentro di me.$B$BMi daranno la caccia e mi esilieranno. Devo nascondermi. Fuggire. Seppellire i corpi.$B$BUscirò quando mi renderò conto di ciò che mi preoccupa davvero.$B$BNon sento sensi di colpa.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2983, 'itIT', 'Per consentire a chi beve l''elisir di vedere i morti, bisogna raccogliere determinati componenti.$B$BPer prima cosa, serve un bulbo oculare del Gronn di Montagna di Nagrand occidentale, vicino le fornaci maledette della Legione Infuocata, a sud del Colle dei Fortemaglio. Sempre a Nagrand occidentale dovrai procurarti un esemplare perfetto di Grifalco Superiore del Vento. L''ultimo componente, che puoi trovare a Nagrand occidentale e sudoccidentale, è il Grasso di Mammuceronte Invecchiato.$B$BRaccogli questi oggetti e portameli! Fa'' presto!$B$BNitrin') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (2998, 'itIT', '$N,$B$Bil Cifrario della Dannazione è un incantesimo davvero potente. Antico e caotico, esso è stato responsabile di molte tragedie nella storia dei nostri mondi. Ciò significa che esso non ha colpito solo Draenor.$B$BIl simbolo infuocato che hai visto era il marchio di Kael''thas. La sua conoscenza delle parole antiche spiega molte cose. La tua scoperta ha risvegliato il Naaru. A''dal ha richiesto la tua presenza a Shattrath. Nel caso accettassi di venire, mi troverai alla Terrazza della Luce.$B$BUmilmente tuo,$BKhadgar') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3001, 'itIT', '<Questa pagina completamente bruciata è illeggibile.>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3039, 'itIT', 'Non restate a piangere sulla mia tomba,
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3057, 'itIT', '<HTML><BODY><H1 align="center">RICERCATO: HEMET NESINGWARY</H1><H1 align="center">PER CRIMINI CONTRO LA NATURA!</H1><BR/><IMG src="Interface\\Pictures\\obj_nesingwary_256" align="center"/><BR/><H1 align="center">Rappresentazione dell''"Annientatore" nel suo habitat naturale: il Fuoco Infernale del mondo sotterraneo.</H1><BR/><H1 align="left">Ultima strage contro l''ecosistema: Nagrand, Terre Esterne</H1><BR/><H1 align="left">Noto anche come: Grande Cacciatore, Macellaio delle Maleterre, Squartatore di Rovotorto, Vecchia Morte, Hemet, Nessie, Vecchio Malandrino, Vecchio Malandrino D, Padre della Caccia, Annientatore</H1></BODY></HTML>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3067, 'itIT', 'Goramosh,$B$Bti invio un rappresentante degli Etereum. L''Ambasciatore Duyheen mi dice che ci sono altri suoi fratelli che vorrebbero unirsi alla causa. Prova a parlare con lui, potrebbe esserci utile. Se sarà il caso, considererò l''ipotesi di accettare dei suoi compagni. Ricorda di non commettere errori: brucia questa lettera dopo averla letta!$B$BM') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3075, 'itIT', 'Salve!$B$BNon so scrivere molto bene, così la matrona mi ha aiutato a preparare questa lettera. Voglio soltanto dirti GRAZIE, perché sei $gun eroe:un''eroina;. Un giorno spero anch''io di salvare la gente, come fai tu.$B$BOra devo andare a giocare, quindi GRAZIE ANCORA! Sei tanto forte e sei anche $gcarino:carina;!$B$B$gLa tua ammiratrice segreta:Il tuo ammiratore segreto;') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3103, 'itIT', 'Giorno 1: la feccia umana sembra non essersi per nulla accorta della mia presenza, come mi aspettavo. Sono pronti a saltare in aria ed è solo questione di tempo prima che io risalga alla loro posizione.$B$BGiorno 2: ho completato il tracciamento, è stato molto facile considerata la mia esperienza. Non capisco perché mi abbiano assegnato questo incarico, avrebbe potuto pensarci J-Y C. Se lo sarebbe meritato, anche solo per quel ridicolo accento.$B$BGiorno 3: finalmente ho respirato una boccata d''aria fresca. Forse dovrei risalire di nuovo, fra qualche giorno. Mi annoio a morte. Quando arriva il segnale?$B$B< Il testo prosegue... >') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3104, 'itIT', 'Giorno 12: ah, che sollievo. La seconda boccata d''aria fresca è stata la cosa più deliziosa che abbia mai provato. Il segnale continua a non giungere e potrei giurare che uno dei granchi stia cercando di suonare il tamburo con il mio alluce.$B$B< Il testo si fa confuso...>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3105, 'itIT', 'Giorno 36: ho consumato la terza scorta d''aria e mentre risalivo le vene nella mia spalla sinistra si sono riempite di nuovo di bolle. Il tambureggiare dei granchi ora è una compagnia costante, uno sfondo di percussioni in questo piccolo angolo nero dell''inferno. Ormai è chiaro che mi hanno dimenticato. Se ci fosse stato J-Y qui, non sarebbe accaduto! Non si sarebbero scordati di Hans o di Sylvian! Perché è successo proprio a me?$B$B<Il testo si perde in una serie di ragionamenti incoerenti...>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3110, 'itIT', 'Al Gran Generale Abbendis$BNuova Avalon, Terre Scarlatte$B$BGran Generale Abbendis,$B$Bspero che la salute vi sia propizia. Il mio nome è Dansel Adams, di professione Cacciatore, Crociato Scarlatto per vocazione. Vi sto scrivendo per dirvi che sono stato testimone di un miracolo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3111, 'itIT', 'Durante una normale operazione di purificazione per mondare la Malaselva infestata dal Flagello, io e il mio gruppo abbiamo udito un terrificante fragore provenire dal cielo. Quando abbiamo guardato in alto, verso Naxxramas, abbiamo visto una cosa incredibile: ve lo assicuro, Gran Generale, non credevamo ai nostri occhi! La cittadella maledetta si stava spostando. Prima si è mossa lentamente e poi, con un rombo di tuono, è sparita! Proprio così, Gran Generale, Naxxramas non c''è più! È svanita! Cosa può essere questo se non un miracolo della Luce?') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3112, 'itIT', 'Ora spero che i prossimi a essere giudicati e condannati siano gli impuri e incivili barbari. Sia lode alla Luce!$B$BFate sapere ai nostri fratelli e alle nostre sorelle di questo miracolo, Gran Generale. Possa la Luce preservarvi per l''eternità, così che possiate diffondere la buona novella fino alla fine dei giorni.$B$BCon rispetto,$B$BD. Adams$B"il Fedele"') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3113, 'itIT', '1. Fatevi crescere una folta barba, perché essa nasconde dalla Luce le imperfezioni del viso.
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3114, 'itIT', '4. Sostituite regolarmente gli abiti sacri, perché il vostro aspetto e il vostro olezzo non offendano i servitori della Luce.
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3117, 'itIT', 'Non è facile parlare di tolleranza, ma in tempi come quelli che stiamo attraversando si tratta di una cosa necessaria. Una mancanza di riflessione, una parola troppo brusca, un pugno o un calcio sferrati in preda alla rabbia... Questi peccati sono comuni tra gli uomini mortali, e la Chiesa deve accettare questo fatto. Questo riconoscimento però comporta un prezzo da pagare. Per peccati legati alle parole, basterà un''offerta in argento per purificare l''anima. Per peccati legati all''uso della forza, sarà necessario ricorrere all''oro. Per peccati di altro genere, si renderanno necessarie una confessione completa e una donazione generosa.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3118, 'itIT', 'Pugni$B$B   Pugno in viso: 2 monete d''oro$B   Pugno al basso ventre: 3 monete d''oro$B   Pugno al petto: 1 moneta d''oro, 45 d''argento$B$B<L''elenco delle donazioni e dei peccati prosegue per diverse pagine>') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3119, 'itIT', 'Purificate il corpo con il lavoro. Purificate l''anima con la preghiera. Purificate i nemici con il fuoco. Il dolore non è un nemico ma un alleato da accogliere e stringere a sé, da trasmettere a credenti e non credenti. La resistenza alle vie della Luce è segno di impurità: la comunità deve liberarsi di questo comportamento.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3120, 'itIT', 'Gran Generale,
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3169, 'itIT', 'BRECCIA DELLA MORTE, REGNI ORIENTALI
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3173, 'itIT', 'SEPULCRA$B$BLe nostre fonti all''interno di Sepulcra indicano che l''Orda si sta mobilitando per lanciare un assalto contro Nordania. "Le truppe dell''Orda, in buona parte rientrate dopo essere state utilizzate nelle Terre Esterne, si stanno radunando per colpire la Corona di Ghiaccio.".') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3174, 'itIT', 'Inoltre, gli agenti infiltrati segnalano che l''Ordine Reale degli Speziali dei Reietti è stato particolarmente attivo, di recente. "Anche se non ci sono conferme, corre voce che l''Ordine abbia compiuto importanti progressi nello studio della Piaga. Si tratta di speculazioni, ma si consiglia a tutte le forze di fare attenzione agli Alchimisti Reietti.".') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3175, 'itIT', 'Cavalieri della Morte di Acherus
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3176, 'itIT', 'Nome: Sixen
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3177, 'itIT', 'Nome: Munch
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3178, 'itIT', 'Nome: Cobalt
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3179, 'itIT', 'Nome: Harmony
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3180, 'itIT', 'Nome: Melt
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3181, 'itIT', 'Nome: Milton
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3182, 'itIT', 'Nome: Minitalis
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3183, 'itIT', 'Nome: $N
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3261, 'itIT', 'Questa è la mia Lama Runica. Ce ne sono tante come lei, ma questa è la mia$BDi Dama Blaumeux$B$BSalute, Cavaliere della Morte. Sicuramente l''Istruttore Razuvious ha già iniziato a spiegarti cosa significa essere un Cavaliere della Morte. Ora io comincerò a rivelarti ciò che devi sapere sul tesoro più prezioso di un Cavaliere della Morte: la Lama Runica.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3262, 'itIT', 'Senza la tua mano a guidarla, la tua Lama Runica è solo un guscio vuoto. Separati siete due entità incomplete, deboli e prive di potere. Se mai dovessi ritrovarti privo di una Lama Runica, sappi che dovrai pensare solamente a procurartene un''altra, nel più breve tempo possibile.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3263, 'itIT', 'Come Cavaliere della Morte, è attraverso la tua Lama Runica che imporrai la tua volontà su tutti coloro che oseranno resistere al Re dei Lich. Proprio come tutti i Cavalieri della Morte sono lo strumento attraverso il quale il Re dei Lich afferma la sua volontà, così la Lama Runica è lo strumento che ti è stato concesso per affermare la tua autorità. Devi comprendere i principi di quest''autorità:') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3264, 'itIT', '1. Quando la impugni, la Lama Runica diventa un''estensione del tuo corpo. E il tuo corpo appartiene al Re dei Lich.$B$B2. La Lama Runica è la manifestazione della tua volontà in forma fisica. E la tua volontà è quella del Re dei Lich.$B$B3. La tua Lama Runica è il tramite che fa giungere la morte alla tua anima. E la tua anima è il tramite della volontà del Re dei Lich.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3265, 'itIT', 'Nel corso del tuo addestramento, potresti trovarti in una situazione in cui dovrai studiare una delle varie discipline a noi accessibili. A riguardo posso dirti solo una cosa: tutte sono meritevoli di studio e trascurarne alcune a beneficio di altre è un''assurdità che, in passato, è già costata la vita a molti Cavalieri della Morte di scarse capacità.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3266, 'itIT', 'Probabilmente presto ti renderai conto che la Lama Runica è un oggetto molto potente nel quale incanalare la tua furia. Questo però non è sufficiente: non limitarti a credere che la Lama Runica sia uno strumento che serve a concentrare la tua capacità di meditazione. No, è molto, molto di più. I più potenti fra noi sono riusciti a comandare il potere delle loro Lame con un semplice pensiero. Combattevano insieme, un solo corpo e una sola mente, pronti a schiacciare chiunque fosse così folle da opporsi a loro.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3267, 'itIT', 'Potresti anche scoprire che la tua Lama risponde in modo più pronto quando è arricchita con il potere di un Toccogelido. In questo modo, anche le Lame Runiche più affilate diventano ancora più letali. Lo stesso potere che permea la gloriosa cittadella della Corona di Ghiaccio viene posto ai tuoi comandi, Cavaliere della Morte. Se deciderai di apprendere questa disciplina i tuoi nemici non avranno scampo, perché le loro azioni saranno rallentate dal gelo.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3268, 'itIT', 'Forse però ti sentirai maggiormente portato al dominio del potere della Lama, per portare la malattia e la piaga sopra i nostri nemici. Anche questo è un nostro potere meritevole di studio. Le difese più potenti possono sembrare impenetrabili, inizialmente, eppure ognuna di esse nasconde dei punti deboli. Si tratta solo di scoprire quali sono. Ricorda, Cavaliere della Morte: Lordaeron è stata distrutta da una piaga, non da un esercito.') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES (3542, 'itIT', 'Arcimago Antonidas$BGran Magus del Kirin Tor$B$BLa splendida città di Dalaran è di nuovo in piedi, a testimonianza della tenacia e della volontà del suo figlio più illustre. I tuoi sacrifici non saranno stati vani, carissimo amico.$B$BCon amore e onore,$B$BJaina Marefiero') ON DUPLICATE KEY UPDATE `Text` = IF(IFNULL(`Text`, '') = '', VALUES(`Text`), `Text`);
